        ('10051111-0000-4000-8000-000000000082', 'अपने क्षेत्र में टूटी स्ट्रीट-लाइटों की मरम्मत के लिए नगर निगम अधिकारी को लगभग 100 शब्दों में एक औपचारिक पत्र लिखिए।', NULL, NULL, 'CASE', 'Hindi', 'रचनात्मक लेखन (अनुच्छेद, पत्र, स्ववृत्त, ई-मेल व विज्ञापन)', 4, 'पूर्ण CBSE बायाँ प्रारूप (प्रेषक पता, दिनांक, नगर निगम अधिकारी, विषय: मोहल्ले की खराब स्ट्रीट-लाइटें ठीक कराने हेतु) + समस्या से होने वाली असुरक्षा/दुर्घटनाएँ + शीघ्र समाधान की प्रार्थना + भवदीय।', 'प्रारूप (1M) + विषयवस्तु (2M) + शुद्ध भाषा (1M)', 'निर्देश: आप कबीर/काव्या, निवासी सी-14, राजेंद्र नगर हैं। पिछले पंद्रह दिनों से आपकी कॉलोनी की सड़क बत्तियाँ खराब हैं।', 'पूर्ण CBSE बायाँ प्रारूप (प्रेषक पता, दिनांक, नगर निगम अधिकारी, विषय: मोहल्ले की खराब स्ट्रीट-लाइटें ठीक कराने हेतु) + समस्या से होने वाली असुरक्षा/दुर्घटनाएँ + शीघ्र समाधान की प्रार्थना + भवदीय।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000083', '"डिजिटल इंडिया और विद्यार्थी जीवन" विषय पर संकेत बिंदुओं के आधार पर 100–120 शब्दों में एक सुगठित अनुच्छेद लिखिए।', NULL, NULL, 'CASE', 'Hindi', 'रचनात्मक लेखन (अनुच्छेद, पत्र, स्ववृत्त, ई-मेल व विज्ञापन)', 4, 'संकेत बिंदु (ई-लर्निंग के लाभ, ज्ञान की सुगम पहुँच, स्क्रीन लत व साइबर सुरक्षा के खतरे, संतुलित उपयोग) को जोड़ते हुए एक ही प्रवाहपूर्ण अनुच्छेद में विचार स्पष्ट, संतुलित व भाषा व्याकरण-सम्मत।', 'सभी बिंदुओं का समावेश (2M) + प्रवाह व शुद्धता (2M)', 'संकेत बिंदु: • डिजिटल शिक्षा का विस्तार • ऑनलाइन संसाधनों का लाभ • अत्यधिक स्क्रीन टाइम की हानि • संतुलित और सुरक्षित प्रयोग।', 'संकेत बिंदु (ई-लर्निंग के लाभ, ज्ञान की सुगम पहुँच, स्क्रीन लत व साइबर सुरक्षा के खतरे, संतुलित उपयोग) को जोड़ते हुए एक ही प्रवाहपूर्ण अनुच्छेद में विचार स्पष्ट, संतुलित व भाषा व्याकरण-सम्मत।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000084', 'एक हिंदी प्रकाशन गृह में "सहायक संपादक" के रिक्त पद हेतु लगभग 80 शब्दों का आवेदन-पत्र लिखिए तथा उसके साथ एक संपूर्ण, सुव्यवस्थित स्ववृत्त (Bio-data) संलग्न कीजिए।', NULL, NULL, 'LA', 'Hindi', 'रचनात्मक लेखन (अनुच्छेद, पत्र, स्ववृत्त, ई-मेल व विज्ञापन)', 5, 'भाग-1: संक्षिप्त औपचारिक आवेदन-पत्र (विज्ञापन संदर्भ सहित) -> भाग-2: व्यवस्थित स्ववृत्त (नाम, पिता का नाम, पता, ई-मेल, शैक्षणिक योग्यता तालिका — 10वीं, 12वीं, स्नातक हिंदी, स्नातकोत्तर/पत्रकारिता डिप्लोमा, भाषा ज्ञान, अनुभव व अभिरुचि)।', 'आवेदन पत्र (2M) + तालिकाबद्ध पूर्ण स्ववृत्त (3M)', NULL, 'भाग-1: संक्षिप्त औपचारिक आवेदन-पत्र (विज्ञापन संदर्भ सहित) -> भाग-2: व्यवस्थित स्ववृत्त (नाम, पिता का नाम, पता, ई-मेल, शैक्षणिक योग्यता तालिका — 10वीं, 12वीं, स्नातक हिंदी, स्नातकोत्तर/पत्रकारिता डिप्लोमा, भाषा ज्ञान, अनुभव व अभिरुचि)।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000085', '[अपठित गद्यांश: "डिजिटल युग में पुस्तकालयों की प्रासंगिकता"]
इंटरनेट और स्मार्टफोन के विस्तार के बावजूद सार्वजनिक एवं विद्यालयी पुस्तकालयों का महत्व कम नहीं हुआ है। जहाँ डिजिटल स्क्रीन पर सूचनाएँ बिखरी हुई और ध्यान भटकाने वाली होती हैं, वहीं पुस्तकालय का शांत वातावरण विद्यार्थियों में एकाग्रता, गहन पठन और आलोचनात्मक चिंतन विकसित करता है। विश्वसनीय संदर्भ ग्रंथों, विश्वकोशों और साहित्यिक कृतियों का प्रामाणिक संग्रह शोध की नींव को मजबूत बनाता है। आधुनिक पुस्तकालय अब ई-पुस्तकों और प्रिंट पुस्तकों का संगम बनकर समावेशी ज्ञान केंद्र के रूप में उभर रहे हैं।

पुस्तकालय का शांत वातावरण विद्यार्थियों में क्या विकसित करता है?', '{"A":"केवल मनोरंजन की आदत","B":"एकाग्रता, गहन पठन और आलोचनात्मक चिंतन","C":"स्क्रीन पर निर्भरता","D":"सूचनाओं का बिखराव"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (B) है। गद्यांश में स्पष्ट है कि शांत वातावरण एकाग्रता, गहन पठन और आलोचनात्मक चिंतन विकसित करता है।', 'सही विकल्प (B) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000086', '[अपठित गद्यांश "डिजिटल युग में पुस्तकालयों की प्रासंगिकता" से] डिजिटल स्क्रीन की सूचनाओं के बारे में लेखक का क्या विचार है?', '{"A":"वे सदैव प्रामाणिक और शांत होती हैं","B":"वे प्रायः बिखरी हुई और ध्यान भटकाने वाली होती हैं","C":"वे पुस्तकालयों से सस्ती होती हैं","D":"उनमें साहित्य नहीं होता"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (B) है। लेखक ने डिजिटल स्क्रीन पर सूचनाओं को बिखरी हुई और ध्यान भटकाने वाली बताया है।', 'सही विकल्प (B) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000087', '[अपठित गद्यांश "डिजिटल युग में पुस्तकालयों की प्रासंगिकता" से] गद्यांश में प्रयुक्त "समावेशी" शब्द का क्या अर्थ है?', '{"A":"सबको साथ लेकर चलने वाला","B":"केवल प्रिंट तक सीमित","C":"अत्यंत महँगा","D":"एकांतप्रिय"}'::jsonb, 'A', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (A) है। ई-पुस्तकों और प्रिंट पुस्तकों दोनों को समेटने वाला ज्ञान केंद्र "समावेशी" कहलाता है।', 'सही विकल्प (A) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000088', '[गद्यांश "डिजिटल युग में पुस्तकालयों की प्रासंगिकता" आधारित] आधुनिक पुस्तकालय किस प्रकार स्वयं को समय के अनुरूप ढाल रहे हैं? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित गद्यांश', 2, 'आधुनिक पुस्तकालय पारंपरिक प्रिंट पुस्तकों व संदर्भ ग्रंथों के साथ-साथ ई-पुस्तकों का समन्वय करके समावेशी ज्ञान केंद्र बन रहे हैं, जिससे विद्यार्थियों को प्रामाणिक सामग्री और शांत अध्ययन परिवेश दोनों मिलते हैं।', 'सटीक तथ्यात्मक उत्तर व स्पष्ट भाषा [2 अंक]', NULL, 'Examiner Tip: उत्तर अपने शब्दों में 30–40 शब्दों में लिखें। | Common Pitfall: पूरा अनुच्छेद ज्यों-का-त्यों उतार देना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000089', '[गद्यांश "डिजिटल युग में पुस्तकालयों की प्रासंगिकता" आधारित] शोध कार्य की नींव को मजबूत बनाने में पुस्तकालयों की क्या भूमिका है? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित गद्यांश', 2, 'पुस्तकालयों में उपलब्ध विश्वसनीय संदर्भ ग्रंथ, विश्वकोश और मौलिक साहित्यिक कृतियाँ विद्यार्थियों को सतही इंटरनेट जानकारी के बजाय प्रामाणिक आधार प्रदान कर शोध को सुदृढ़ बनाती हैं।', 'सटीक तथ्यात्मक उत्तर व स्पष्ट भाषा [2 अंक]', NULL, 'Examiner Tip: उत्तर अपने शब्दों में 30–40 शब्दों में लिखें। | Common Pitfall: पूरा अनुच्छेद ज्यों-का-त्यों उतार देना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000008a', '[अपठित काव्यांश: "नव-प्रभात का संकल्प"]
तिमिर घना कितना भी छाया,
दीपक ने कब हार मानी?
बूँद-बूँद से घट भर जाता,
लहरों ने कब थामी रवानी।
काँटों के पथ पर भी चलकर,
फूलों ने मुस्कान बिखेरी,
दृढ़ निश्चय के आगे हरदम,
टूट गई बाधा की बेरी।

कविता में "दीपक" किस मानवीय गुण का प्रतीक है?', '{"A":"आलस्य और निराशा","B":"कठिन परिस्थितियों में भी आशा और संघर्ष","C":"अंधकार का भय","D":"स्वार्थ"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (B) है। घने तिमिर (अंधकार) में भी न हार मानने वाला दीपक आशा और अविरत संघर्ष का प्रतीक है।', 'सही विकल्प (B) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000008b', '[अपठित काव्यांश "नव-प्रभात का संकल्प" से] "बूँद-बूँद से घट भर जाता" पंक्ति क्या संदेश देती है?', '{"A":"छोटे-छोटे निरंतर प्रयासों से बड़ा लक्ष्य सिद्ध होता है","B":"जल व्यर्थ बहाना चाहिए","C":"घड़ा कभी नहीं भरता","D":"लहरें रुक जाती हैं"}'::jsonb, 'A', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (A) है। यह पंक्ति निरंतर छोटे प्रयासों की शक्ति को दर्शाती है।', 'सही विकल्प (A) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000008c', '[अपठित काव्यांश "नव-प्रभात का संकल्प" से] "तिमिर" शब्द का पर्यायवाची चुनिए:', '{"A":"प्रकाश","B":"अंधकार","C":"प्रभात","D":"सागर"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (B) है। तिमिर का अर्थ अंधकार/अँधेरा है।', 'सही विकल्प (B) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000008d', '[काव्यांश "नव-प्रभात का संकल्प" आधारित] काँटों और फूलों के माध्यम से कवि क्या प्रेरणा देना चाहता है? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित काव्यांश', 2, 'कवि यह प्रेरणा देता है कि जीवन में चाहे जितनी कठिनाइयाँ (काँटे) आएँ, मनुष्य को फूलों की तरह सकारात्मक रहकर अपने सद्गुणों और मुस्कान से संसार को महकाना चाहिए।', 'काव्य-भाव की सटीक व्याख्या [2 अंक]', NULL, 'Examiner Tip: भावार्थ सरल और सटीक हिंदी में लिखें। | Common Pitfall: अलंकार या संदर्भ से भटक जाना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000008e', '[काव्यांश "नव-प्रभात का संकल्प" आधारित] कविता का उपयुक्त शीर्षक लिखकर "बाधा की बेरी" टूटने का आशय स्पष्ट कीजिए। (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित काव्यांश', 2, 'शीर्षक: "दृढ़ निश्चय की विजय"। आशय यह है कि जब व्यक्ति अटल संकल्प के साथ आगे बढ़ता है, तो रास्ते की बड़ी-से-बड़ी रुकावटें स्वयं समाप्त हो जाती हैं।', 'काव्य-भाव की सटीक व्याख्या [2 अंक]', NULL, 'Examiner Tip: भावार्थ सरल और सटीक हिंदी में लिखें। | Common Pitfall: अलंकार या संदर्भ से भटक जाना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000008f', '"जो विद्यार्थी परिश्रम करते हैं, वे बोर्ड परीक्षा में अवश्य सफल होते हैं।" — रचना के आधार पर वाक्य का भेद पहचानिए:', '{"A":"सरल वाक्य","B":"संयुक्त वाक्य","C":"मिश्र वाक्य","D":"प्रश्नवाचक वाक्य"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। "जो... वे" योजक से जुड़ा एक प्रधान व एक आश्रित उपवाक्य होने के कारण यह मिश्र वाक्य है।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000090', '"सूरज निकला और पक्षी चहचहाने लगे।" इस वाक्य का सरल वाक्य में रूपांतरण होगा:', '{"A":"जब सूरज निकला, तब पक्षी चहचहाने लगे।","B":"सूरज निकलते ही पक्षी चहचहाने लगे।","C":"चूँकि सूरज निकला इसलिए पक्षी चहचहाए।","D":"सूरज निकला तथा पक्षी चहचहाने लगे।"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। एक ही मुख्य क्रिया ("चहचहाने लगे") में परिवर्तित करने पर "सूरज निकलते ही पक्षी चहचहाने लगे" सरल वाक्य बनता है।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000091', '"घंटी बजते ही सभी छात्र कक्षा में चले गए।" — इसका संयुक्त वाक्य रूप चुनिए:', '{"A":"जैसे ही घंटी बजी, सभी छात्र कक्षा में चले गए।","B":"घंटी बजी और सभी छात्र कक्षा में चले गए।","C":"जब घंटी बजी तब छात्र चले गए।","D":"घंटी बजने के कारण छात्र कक्षा में गए।"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। दो स्वतंत्र उपवाक्यों को समानाधिकरण योजक "और" से जोड़ने पर संयुक्त वाक्य बनता है।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000092', '"कठोर होने के कारण पत्थर भी टूट जाता है।" — वाक्य भेद बताइए:', '{"A":"सरल वाक्य","B":"संयुक्त वाक्य","C":"मिश्र वाक्य","D":"इच्छावाचक वाक्य"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। इसमें एक उद्देश्य और एक ही मुख्य विधेय/समापिका क्रिया है, अतः यह सरल वाक्य है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000093', '"तुलसीदास ने रामचरितमानस की रचना की।" — इस वाक्य में कौन-सा वाच्य है?', '{"A":"कर्तृवाच्य","B":"कर्मवाच्य","C":"भाववाच्य","D":"इनमें से कोई नहीं"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। कर्ता ("तुलसीदास ने") की प्रधानता होने तथा सकर्मक क्रिया के कर्ता-केन्द्रित प्रयोग से यहाँ कर्तृवाच्य है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000094', '"बच्चों से अब चला नहीं जाता।" — वाच्य का भेद बताइए:', '{"A":"कर्तृवाच्य","B":"कर्मवाच्य","C":"भाववाच्य","D":"मिश्र वाच्य"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। अकर्मक क्रिया ("चला नहीं जाता"), अन्य पुरुष एकवचन और असमर्थता के भाव के कारण भाववाच्य है।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000095', '"किसानों द्वारा खेत जोते गए।" — इसका कर्तृवाच्य रूप क्या होगा?', '{"A":"किसानों ने खेत जोते।","B":"किसान से खेत जोता गया।","C":"खेत किसानों द्वारा जोते जाते हैं।","D":"किसानों द्वारा खेत जोता जाएगा।"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। "द्वारा" हटाकर कर्ता को प्रधान बनाने पर "किसानों ने खेत जोते" कर्तृवाच्य बनता है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000096', '"रमा पुस्तक पढ़ती है।" — इसका कर्मवाच्य में रूपांतरण चुनिए:', '{"A":"रमा पुस्तक पढ़ेगी।","B":"रमा से पढ़ा नहीं जाता।","C":"रमा द्वारा पुस्तक पढ़ी जाती है।","D":"रमा ने पुस्तक पढ़ी।"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। कर्मवाच्य में "द्वारा/से" जुड़ता है और क्रिया कर्म ("पुस्तक" स्त्रीलिंग) के अनुसार "पढ़ी जाती है" होती है।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000097', '"**हिमालय** भारत के उत्तर में स्थित है।" — रेखांकित शब्द "हिमालय" का सही पद-परिचय है:', '{"A":"जातिवाचक संज्ञा, स्त्रीलिंग, एकवचन, कर्ता कारक","B":"व्यक्तिवाचक संज्ञा, पुल्लिंग, एकवचन, कर्ता कारक","C":"भाववाचक संज्ञा, पुल्लिंग, बहुवचन","D":"विशेषण, पुल्लिंग, एकवचन"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। हिमालय विशेष पर्वत का नाम है -> व्यक्तिवाचक संज्ञा, पुल्लिंग, एकवचन, कर्ता कारक।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000098', '"यह **मेरी** प्रिय पुस्तक है।" — रेखांकित पद "मेरी" का उचित पद-परिचय चुनिए:', '{"A":"उत्तम पुरुषवाचक/सार्वनामिक विशेषण, स्त्रीलिंग, एकवचन, विशेष्य \"पुस्तक\"","B":"व्यक्तिवाचक संज्ञा, पुल्लिंग","C":"अकर्मक क्रिया, वर्तमान काल","D":"कालवाचक क्रियाविशेषण"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। "मेरी" संज्ञा "पुस्तक" से पहले आकर अधिकार/संबंध बता रहा है -> सार्वनामिक विशेषण / संबंध कारक सर्वनाम, स्त्रीलिंग, एकवचन।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000099', '"छात्र **धीरे-धीरे** सीढ़ियाँ चढ़ रहे थे।" — रेखांकित पद "धीरे-धीरे" का पद-परिचय होगा:', '{"A":"स्थानवाचक क्रियाविशेषण","B":"रीतिवाचक क्रियाविशेषण, \"चढ़ रहे थे\" क्रिया की विशेषता","C":"गुणवाचक विशेषण","D":"समुच्चयबोधक अव्यय"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। "धीरे-धीरे" चढ़ने की रीति (ढंग) बताता है -> रीतिवाचक क्रियाविशेषण।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009a', '"वाह! **तुमने** तो कमाल कर दिया।" — रेखांकित पद "तुमने" का पद-परिचय चुनिए:', '{"A":"मध्यम पुरुषवाचक सर्वनाम, एकवचन, कर्ता कारक","B":"उत्तम पुरुषवाचक सर्वनाम, बहुवचन","C":"निजवाचक सर्वनाम","D":"प्रश्नवाचक सर्वनाम"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। "तुमने" सुनने वाले के लिए प्रयुक्त मध्यम पुरुषवाचक सर्वनाम, कर्ता कारक ("ने" परसर्ग) है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009b', '"पानी गए न ऊबरै, मोती मानुष चून।" — में कौन-सा अलंकार है?', '{"A":"श्लेष अलंकार","B":"अतिशयोक्ति अलंकार","C":"मानवीकरण अलंकार","D":"रूपक अलंकार"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। यहाँ एक शब्द "पानी" के तीन अर्थ (चमक, सम्मान, जल) चिपके हैं, अतः श्लेष अलंकार है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009c', '"देख लो साकेत नगरी है यही, स्वर्ग से मिलने गगन में जा रही।" — इसमें कौन-सा अलंकार है?', '{"A":"श्लेष","B":"उत्प्रेक्षा","C":"अतिशयोक्ति अलंकार","D":"यमक"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। नगरी की ऊँचाई का लोक-सीमा से बढ़ा-चढ़ाकर वर्णन करने के कारण अतिशयोक्ति अलंकार है।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009d', '"मेघ आए बड़े बन-ठन के सँवर के।" — इस काव्य पंक्ति में कौन-सा अलंकार प्रयुक्त हुआ है?', '{"A":"मानवीकरण अलंकार","B":"श्लेष अलंकार","C":"अतिशयोक्ति अलंकार","D":"अनुप्रास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। जड़/प्राकृतिक बादलों पर सँवरकर आने की मानवीय चेष्टा का आरोप होने से मानवीकरण अलंकार है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009e', '"कहती हुई यों उत्तरा के नेत्र जल से भर गए। हिम के कणों से पूर्ण मानो हो गए पंकज नए।" — पंक्ति में अलंकार है:', '{"A":"मानवीकरण","B":"उत्प्रेक्षा अलंकार","C":"श्लेष","D":"उपमा"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। वाचक शब्द "मानो" द्वारा उपमेय में उपमान की संभावना व्यक्त होने से उत्प्रेक्षा अलंकार है।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000009f', 'पठित पाठ "नेताजी का चश्मा" के आधार पर निम्नलिखित प्रश्नों के उत्तर दीजिए (5 अंक):
(क) हालदार साहब को पानवाले की कौन-सी बात अच्छी नहीं लगी जब उन्होंने कैप्टन चश्मेवाले के बारे में पूछा? (2M)
(ख) अंत में बच्चों द्वारा नेताजी की मूर्ति पर सरकंडे का चश्मा लगा देखकर हालदार साहब भावुक क्यों हो उठे? (2M)
(ग) कैप्टन की देशभक्ति किस रूप में प्रकट होती थी? (1M)', NULL, NULL, 'LA', 'Hindi', 'क्षितिज गद्य', 5, '(क) जब पानवाले ने देशभक्त कैप्टन का मज़ाक उड़ाते हुए कहा कि "वह लँगड़ा क्या जाएगा फ़ौज में, पागल है पागल", तब देशभक्त का उपहास हालदार साहब को बिल्कुल अच्छा नहीं लगा।
(ख) सरकंडे का चश्मा देखकर उन्हें विश्वास हो गया कि आज भी भावी पीढ़ी (बच्चों) के मन में देशभक्तों के प्रति सम्मान और देशप्रेम की भावना जीवित है।
(ग) वह नेताजी की बिना चश्मे वाली मूर्ति पर रोज़ अपनी दुकान से असली चश्मा पहनाकर अपनी श्रद्धा प्रकट करता था।', '(क) पानवाले की संवेदनहीन टिप्पणी [2 Marks] | (ख) नई पीढ़ी में देशभक्ति का विश्वास [2 Marks] | (ग) मूर्ति पर चश्मा लगाने का कार्य [1 Mark]', NULL, 'Examiner Tip: सरकंडे के चश्मे का प्रतीकात्मक महत्व (भावी पीढ़ी में देशभक्ति) अवश्य लिखें। | Common Pitfall: कैप्टन को वास्तविक सेना का सिपाही समझ बैठना।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000a0', 'पठित काव्य पाठों के आधार पर उत्तर दीजिए (5 अंक):
(क) गोपियों ने उद्धव को "बड़भागी" कहकर उन पर क्या व्यंग्य किया है? (2M)
(ख) "राम-लक्ष्मण-परशुराम संवाद" में लक्ष्मण ने वीर योद्धा की क्या विशेषताएँ बताई हैं? (2M)
