        ('10051111-0000-4000-8000-0000000000ad', '[अपठित गद्यांश: "जल संरक्षण और पारंपरिक भारतीय जल-स्रोत"]
भारत की पारंपरिक जल-प्रबंधन प्रणाली प्रकृति के साथ सामंजस्य का जीवंत उदाहरण रही है। प्राचीन काल में बावलियाँ, जोहड़, तालाब और कुएँ केवल जल संग्रहण के साधन नहीं थे, बल्कि सामुदायिक सहभागिता के केंद्र भी थे। वर्षा की हर बूँद को सहेजने की लोक-संस्कृति ने सूखे क्षेत्रों को भी हरा-भरा रखा। आज अनियंत्रित भू-जल दोहन और कंक्रीट के बढ़ते जाल ने भूमिगत जल-स्तर को गंभीर संकट में डाल दिया है। यदि हम आधुनिक तकनीक के साथ-साथ पारंपरिक वर्षा जल संचयन को अपनाएँ, तो भावी पीढ़ियों के लिए जल सुरक्षा सुनिश्चित की जा सकती है।

प्राचीन भारत में बावलियाँ और जोहड़ किस बात के प्रतीक थे?', '{"A":"अनियंत्रित दोहन के","B":"जल संग्रहण और सामुदायिक सहभागिता के","C":"औद्योगिक प्रदूषण के","D":"केवल राजमहलों की शोभा के"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (B) है। बावलियाँ, जोहड़ और तालाब जल संग्रहण के साथ सामुदायिक सहभागिता के केंद्र थे।', 'सही विकल्प (B) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000ae', '[अपठित गद्यांश "जल संरक्षण और पारंपरिक भारतीय जल-स्रोत" से] वर्तमान में भूमिगत जल-स्तर के संकट का प्रमुख कारण क्या बताया गया है?', '{"A":"वर्षा जल संचयन","B":"अनियंत्रित भू-जल दोहन और कंक्रीट का बढ़ता जाल","C":"लोक-संस्कृति का विकास","D":"तालाबों की खुदाई"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (B) है। अनियंत्रित भू-जल दोहन और कंक्रीट के जाल ने जल-स्तर को संकट में डाला है।', 'सही विकल्प (B) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000af', '[अपठित गद्यांश "जल संरक्षण और पारंपरिक भारतीय जल-स्रोत" से] "सामंजस्य" शब्द का उपयुक्त अर्थ चुनिए:', '{"A":"टकराव","B":"तालमेल / संतुलन","C":"विरोध","D":"उपेक्षा"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित गद्यांश', 1, 'सही विकल्प (B) है। सामंजस्य का अर्थ संतुलन या तालमेल है।', 'सही विकल्प (B) का चयन [1 अंक]', NULL, 'Examiner Tip: गद्यांश की मूल पंक्तियों से उत्तर की पुष्टि करें। | Common Pitfall: अपनी कल्पना से गद्यांश के बाहर का उत्तर चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b0', '[गद्यांश "जल संरक्षण और पारंपरिक भारतीय जल-स्रोत" आधारित] पारंपरिक जल-स्रोतों ने सूखे क्षेत्रों में जीवन को किस प्रकार संभव बनाया? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित गद्यांश', 2, 'बावलियों, जोहड़ों और तालाबों के माध्यम से सामुदायिक सहभागिता द्वारा वर्षा की प्रत्येक बूँद का संचयन किया जाता था, जिससे भू-जल रिचार्ज होता रहा और सूखे क्षेत्रों में भी हरियाली बनी रही।', 'सटीक तथ्यात्मक उत्तर व स्पष्ट भाषा [2 अंक]', NULL, 'Examiner Tip: उत्तर अपने शब्दों में 30–40 शब्दों में लिखें। | Common Pitfall: पूरा अनुच्छेद ज्यों-का-त्यों उतार देना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000b1', '[गद्यांश "जल संरक्षण और पारंपरिक भारतीय जल-स्रोत" आधारित] भावी पीढ़ियों के लिए जल सुरक्षा कैसे सुनिश्चित की जा सकती है? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित गद्यांश', 2, 'अनियंत्रित भू-जल दोहन पर रोक लगाकर तथा आधुनिक जल-प्रबंधन तकनीक के साथ पारंपरिक वर्षा जल संचयन प्रणालियों को पुनर्जीवित करके जल सुरक्षा सुनिश्चित की जा सकती है।', 'सटीक तथ्यात्मक उत्तर व स्पष्ट भाषा [2 अंक]', NULL, 'Examiner Tip: उत्तर अपने शब्दों में 30–40 शब्दों में लिखें। | Common Pitfall: पूरा अनुच्छेद ज्यों-का-त्यों उतार देना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000b2', '[अपठित काव्यांश: "श्रम और धरा का गीत"]
माटी को जो सींचे स्वेद से,
सोना वही उगाता है,
बाँध भला कब रोक सका है,
सरिता जब बल खाती है।
बैठे-बैठे भाग्य को कोसें,
उनसे राह न बन पाती,
धूप-छाँव सहने वालों की,
कीर्ति युगों तक गाती है।

"माटी को जो सींचे स्वेद से" से कवि का क्या तात्पर्य है?', '{"A":"वर्षा से सिंचाई करना","B":"कठोर परिश्रम (पसीने) से धरती पर कार्य करना","C":"मिट्टी से खेलना","D":"केवल विश्राम करना"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (B) है। स्वेद का अर्थ पसीना है—अर्थात् कठोर श्रम करने वाला व्यक्ति ही सफलता (सोना) पाता है।', 'सही विकल्प (B) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b3', '[अपठित काव्यांश "श्रम और धरा का गीत" से] कवि के अनुसार कौन लोग जीवन में राह नहीं बना पाते?', '{"A":"धूप-छाँव सहने वाले","B":"बैठकर केवल भाग्य को कोसने वाले","C":"सरिता के समान गतिशील लोग","D":"परिश्रमी किसान"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (B) है। कवि स्पष्ट कहता है कि बैठे-बैठे भाग्य को कोसने वालों से राह नहीं बनती।', 'सही विकल्प (B) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b4', '[अपठित काव्यांश "श्रम और धरा का गीत" से] "सरिता" शब्द का सही अर्थ है:', '{"A":"पर्वत","B":"नदी","C":"बादल","D":"वृक्ष"}'::jsonb, 'B', 'MCQ', 'Hindi', 'अपठित काव्यांश', 1, 'सही विकल्प (B) है। सरिता का अर्थ नदी है।', 'सही विकल्प (B) [1 अंक]', NULL, 'Examiner Tip: कविता के प्रतीकात्मक भाव को समझकर विकल्प चुनें। | Common Pitfall: शाब्दिक अर्थ के भ्रम में गलत विकल्प चुनना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b5', '[काव्यांश "श्रम और धरा का गीत" आधारित] कवि ने गतिशीलता और श्रम को किस उदाहरण द्वारा समझाया है? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित काव्यांश', 2, 'कवि ने वेग से बहती सरिता (नदी) और पसीने से मिट्टी सींचने वाले श्रमिक के उदाहरण से समझाया है कि सच्चा परिश्रम और गतिशीलता हर अवरोध को पार कर लेते हैं।', 'काव्य-भाव की सटीक व्याख्या [2 अंक]', NULL, 'Examiner Tip: भावार्थ सरल और सटीक हिंदी में लिखें। | Common Pitfall: अलंकार या संदर्भ से भटक जाना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000b6', '[काव्यांश "श्रम और धरा का गीत" आधारित] "धूप-छाँव सहने वालों की कीर्ति" से क्या आशय है? (30–40 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'अपठित काव्यांश', 2, 'सुख-दुख और अनुकूल-प्रतिकूल दोनों परिस्थितियों में धैर्यपूर्वक कर्म करने वाले लोगों का यश और सम्मान युगों तक जीवित रहता है।', 'काव्य-भाव की सटीक व्याख्या [2 अंक]', NULL, 'Examiner Tip: भावार्थ सरल और सटीक हिंदी में लिखें। | Common Pitfall: अलंकार या संदर्भ से भटक जाना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000b7', '"यद्यपि वह निर्धन है, तथापि ईमानदार है।" — यह किस प्रकार का आश्रित उपवाक्य युक्त वाक्य है?', '{"A":"सरल वाक्य","B":"संयुक्त वाक्य","C":"मिश्र वाक्य","D":"संदेहवाचक वाक्य"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। "यद्यपि... तथापि" से जुड़ा होने के कारण यह मिश्र वाक्य है।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b8', 'निम्नलिखित में से कौन-सा वाक्य कर्मवाच्य का उदाहरण है?', '{"A":"पक्षी आकाश में उड़ते हैं।","B":"श्याम ने सुंदर चित्र बनाया।","C":"सरकार द्वारा गरीबों को कंबल बाँटे गए।","D":"रोगी से बैठा नहीं जाता।"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (C) है। "सरकार द्वारा" + कर्म ("कंबल") के अनुसार क्रिया ("बाँटे गए") -> कर्मवाच्य।', 'सटीक व्याकरणिक चयन (C) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000b9', '"मेज़ पर **चार** किताबें रखी हैं।" — रेखांकित पद "चार" का पद-परिचय है:', '{"A":"अनिश्चित परिमाणवाचक विशेषण","B":"निश्चित संख्यावाचक विशेषण, बहुवचन, विशेष्य \"किताबें\"","C":"गुणवाचक विशेषण","D":"भाववाचक संज्ञा"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (B) है। गिनती निश्चित "चार" होने के कारण निश्चित संख्यावाचक विशेषण।', 'सटीक व्याकरणिक चयन (B) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000ba', '"मंगन को देखि पट देत बार-बार है।" — में कौन-सा अलंकार है?', '{"A":"श्लेष अलंकार","B":"उत्प्रेक्षा","C":"अतिशयोक्ति","D":"मानवीकरण"}'::jsonb, 'A', 'MCQ', 'Hindi', 'व्याकरण', 1, 'सही विकल्प (A) है। "पट" शब्द के दो अर्थ (वस्त्र और किवाड़) एक ही प्रयोग में होने से श्लेष अलंकार है।', 'सटीक व्याकरणिक चयन (A) [1 अंक]', NULL, 'Examiner Tip: वाक्य में योजक, परसर्ग और क्रिया के लिंग-वचन ध्यान से देखें। | Common Pitfall: सरल, संयुक्त व मिश्र वाक्यों के योजकों में भ्रमित होना।', 'EASY', true),
        ('10051111-0000-4000-8000-0000000000bb', 'पठित पाठ "बालगोबिन भगत" के संदर्भ में उत्तर दीजिए (5 अंक):
(क) भगत जी गृहस्थ होते हुए भी "साधु" की किन परिभाषाओं पर खरे उतरते थे? (2M)
(ख) पुत्र की मृत्यु के बाद भगत ने अपनी पतोहू के साथ कैसा प्रगतिशील व्यवहार किया? (2M)
(ग) कबीर के प्रति उनकी श्रद्धा किस रूप में दिखती थी? (1M)', NULL, NULL, 'LA', 'Hindi', 'क्षितिज गद्य', 5, '(क) वे कभी झूठ नहीं बोलते थे, खरा व्यवहार रखते थे, किसी की चीज़ बिना पूछे नहीं छूते थे तथा अपनी उपज का हिस्सा कबीरपंथी मठ में चढ़ाकर जो प्रसाद मिलता, उसी से निर्वाह करते थे।
(ख) उन्होंने पतोहू को रोने के बजाय उत्सव मनाने (आत्मा-परमात्मा मिलन) को कहा, उसी से पुत्र की चिता को मुखाग्नि दिलाई और बाद में उसके भाई को बुलाकर पुनर्विवाह करने का आदेश दिया।
(ग) वे कबीर को "साहब" मानते थे और उन्हीं के पदों का मधुर गायन करते थे।', '(क) सत्यनिष्ठा व अपरिग्रह आचरण [2 Marks] | (ख) पतोहू से मुखाग्नि व पुनर्विवाह का सामाजिक सुधार [2 Marks] | (ग) कबीर के पद गायन [1 Mark]', NULL, 'Examiner Tip: सामाजिक रूढ़ियों (स्त्रियों द्वारा दाह संस्कार निषेध व विधवा पुनर्विवाह विरोध) पर प्रहार का उल्लेख करें। | Common Pitfall: केवल उनके गायन का वर्णन कर सुधारवादी पक्ष छोड़ देना।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000bc', 'पठित काव्य पाठों के आधार पर उत्तर दीजिए (5 अंक):
(क) निराला ने कविता "उत्साह" में बादल का आह्वान किस रूप में किया है—रिमझिम बरसने के लिए या गरजने के लिए, और क्यों? (2M)
(ख) "संगतकार" कविता में संगतकार मुख्य गायक का साथ किस प्रकार देता है और अपनी आवाज़ को ऊँचा क्यों नहीं उठने देता? (2M)
(ग) "अट नहीं रही है" कविता किस ऋतु के अनुपम सौंदर्य पर केंद्रित है? (1M)', NULL, NULL, 'LA', 'Hindi', 'क्षितिज काव्य', 5, '(क) कवि ने बादल का आह्वान "गरजकर" बरसने (विप्लव और नव-निर्माण) के लिए किया है ताकि तपते हुए संसार को शीतलता मिले और जड़ता में क्रांति व नई चेतना जागृत हो।
(ख) जब मुख्य गायक का स्वर टूटने लगता है या वह अंतरे की जटिल तानों में भटक जाता है, तब संगतकार स्थायी को सँभालता है। वह जानबूझकर अपनी आवाज़ धीमी रखता है ताकि मुख्य गायक की गरिमा बनी रहे—यह मानवीय संवेदनशीलता है, कमज़ोरी नहीं।
(ग) फागुन (वसंत) ऋतु।', '(क) गरजना = क्रांति व नवजीवन चेतना [2 Marks] | (ख) मुख्य गायक को सँभालना व संवेदनशील त्याग [2 Marks] | (ग) फागुन मास [1 Mark]', NULL, 'Examiner Tip: संगतकार की हिचक को "मनुष्यता / विनम्रता" बताएँ, अयोग्यता नहीं। | Common Pitfall: "उत्साह" में बादल को केवल वर्षा का साधन लिखना बिना क्रांति भाव के।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000bd', 'लेखक के अनुसार "सभ्यता" और "संस्कृति" में क्या मौलिक अंतर है? आग और सुई-धागे के उदाहरण से समझाइए। (25–30 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'क्षितिज गद्य', 2, 'किसी नई चीज़ की खोज करने की आंतरिक प्रेरणा व योग्यता "संस्कृति" है, जबकि उस खोज से प्राप्त आविष्कार (आग, सुई-धागा) और उसके बाहरी उपयोग "सभ्यता" कहलाते हैं।', 'मूल पाठगत बिंदु (1.5 अंक) + शुद्ध भाषा (0.5 अंक) [2 अंक]', NULL, 'Examiner Tip: सीधे मुख्य बिंदु लिखें, अनावश्यक भूमिका न बनाएँ। | Common Pitfall: लेखक के व्यंग्य या मर्म को स्पष्ट न करना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000be', 'कविता "उत्साह" में "तप्त धरा" का सांकेतिक अर्थ क्या है? (25–30 शब्द)', NULL, NULL, 'VSA', 'Hindi', 'क्षितिज काव्य', 2, '"तप्त धरा" का शाब्दिक अर्थ गर्मी से तपती धरती है, किंतु सांकेतिक रूप से यह शोषण, अन्याय और दुखों से त्रस्त पीड़ित मानव समाज का प्रतीक है।', 'काव्य-मर्म स्पष्टीकरण (1.5 अंक) + भाषा (0.5 अंक) [2 अंक]', NULL, 'Examiner Tip: कविता के मुख्य प्रतीकों का उल्लेख अवश्य करें। | Common Pitfall: केवल कविता का शब्दार्थ लिखकर छोड़ देना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-0000000000bf', 'लेखक अज्ञेय ने हिरोशिमा के अनुभव के माध्यम से "प्रत्यक्ष अनुभव" और "गहरी अनुभूति" के बीच क्या अंतर बताया है? (50–60 शब्द)', NULL, NULL, 'SA', 'Hindi', 'कृतिका', 4, 'अज्ञेय के अनुसार प्रत्यक्ष अनुभव सामने घटित घटना को देखने मात्र से होता है, जबकि सच्ची अनुभूति संवेदना और कल्पना के सहारे उस सत्य को भीतर से जी लेने से उत्पन्न होती है। हिरोशिमा में पत्थर पर छपी मानव-छाया देखकर उन्हें अणुबम की त्रासदी की गहरी अनुभूति हुई, जिसने उन्हें "हिरोशिमा" कविता लिखने को विवश किया।', 'पात्र/घटना का सटीक संदर्भ (2 अंक) + विचार विश्लेषण (2 अंक) [4 अंक]', NULL, 'Examiner Tip: 50–60 शब्दों में मानवीय संवेदना या सामाजिक संदेश को उभारें। | Common Pitfall: केवल कहानी सुनाकर निष्कर्ष न लिखना।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000c0', 'निम्नलिखित विषय पर संकेत-बिंदुओं के आधार पर लगभग 120 शब्दों में अनुच्छेद लिखिए (6 अंक):
• खेलों का जीवन में महत्व (संकेत बिंदु: स्वास्थ्य और स्फूर्ति, अनुशासन व टीम भावना, तनाव से मुक्ति, करियर की संभावनाएँ)', NULL, NULL, 'LA', 'Hindi', 'रचनात्मक लेखन', 6, 'खेलों का जीवन में महत्व

कहा गया है कि "स्वस्थ शरीर में ही स्वस्थ मस्तिष्क का निवास होता है", और शरीर को स्वस्थ रखने का सर्वोत्तम माध्यम खेल हैं। नियमित खेलकूद से शारीरिक स्फूर्ति, सहनशक्ति और रोग-प्रतिरोधक क्षमता बढ़ती है। विद्यार्थी जीवन में पढ़ाई के मानसिक दबाव और तनाव को कम करने में खेल संजीवनी का कार्य करते हैं। मैदान में खेलते समय छात्र अनुशासन, समय-पालन, नेतृत्व, सहयोग और टीम भावना जैसे अनमोल जीवन-कौशल सीखते हैं। हार को सहजता से स्वीकार कर पुनः प्रयास करने की खेल-भावना जीवन के हर संघर्ष में काम आती है। आज खेल केवल मनोरंजन तक सीमित नहीं हैं, बल्कि राष्ट्रीय और अंतरराष्ट्रीय स्तर पर सम्मानजनक करियर का सशक्त माध्यम भी बन चुके हैं। अतः पढ़ाई और खेलों में संतुलन अनिवार्य है।', 'विषय-प्रवेश एवं सूक्ति [1.5 Marks] | सभी संकेत बिंदुओं का तार्किक विकास [3 Marks] | वर्तनी एवं व्याकरण शुद्धता [1.5 Marks]', NULL, 'Examiner Tip: प्रारंभ में एक सटीक सूक्ति जोड़ने से प्रभाव उत्कृष्ट होता है। | Common Pitfall: 120 शब्दों की सीमा से बहुत अधिक या बहुत कम लिखना।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000c1', 'आपका छोटा भाई छात्रावास में रहता है और जंक फूड तथा मोबाइल गेमिंग की लत से प्रभावित हो रहा है। उसे संतुलित आहार और समय प्रबंधन का महत्व समझाते हुए लगभग 100 शब्दों में पत्र लिखिए।', NULL, NULL, 'LA', 'Hindi', 'रचनात्मक लेखन', 5, 'परीक्षा भवन
अ.ब.स. नगर

दिनांक: 26 नवंबर 2026

प्रिय अनुज आयुष,
शुभाशीष!

कल छात्रावास से तुम्हारे मित्र का फोन आया तो पता चला कि आजकल तुम देर रात तक मोबाइल गेम खेलते हो और मेस के पौष्टिक भोजन के बजाय बाहरी जंक फूड अधिक खाने लगे हो। प्रिय भाई, यह विद्यार्थी जीवन के लिए अत्यंत हानिकारक है। जंक फूड से पाचन व एकाग्रता कमजोर होती है और स्क्रीन की लत आँखों तथा परीक्षा परिणाम दोनों को नुकसान पहुँचाती है।

मेरा सुझाव है कि प्रतिदिन एक निश्चित समय-सारिणी बनाओ, सुबह व्यायाम करो, फल-दूध व संतुलित आहार लो तथा मोबाइल का उपयोग केवल अध्ययन के लिए सीमित रखो। आशा है तुम मेरी बात मानोगे।

तुम्हारा बड़ा भाई,
क.ख.ग.', 'अनौपचारिक प्रारूप व स्नेहपूर्ण संबोधन [1.5 Marks] | पौष्टिक आहार व समय प्रबंधन के सुझाव [2.5 Marks] | भावपूर्ण व शुद्ध भाषा [1 Mark]', NULL, 'Examiner Tip: अनौपचारिक पत्र में "विषय" नहीं लिखा जाता और समापन में "भवदीय" की जगह "तुम्हारा भाई/मित्र" आता है। | Common Pitfall: अनौपचारिक पत्र में "विषय" लिख देना।', 'HARD', true),
        ('10051111-0000-4000-8000-0000000000c2', 'राजकीय सर्वोदय विद्यालय में "पुस्तकालय सहायक" के रिक्त पद पर आवेदन करने हेतु लगभग 80 शब्दों में एक व्यवस्थित स्ववृत्त (Bio-Data) तैयार कीजिए।', NULL, NULL, 'LA', 'Hindi', 'रचनात्मक लेखन', 5, 'सेवा में,
