        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10051111-0000-4000-8000-000000000001', 'गोपियों ने उद्धव को "बड़भागी" क्यों कहा है?', '{"A":"वे बहुत धनवान थे","B":"श्रीकृष्ण के पास रहकर भी वे उनके प्रेम-बंधन से अछूते रहे (व्यंग्य)","C":"वे राजा बन गए","D":"वे मथुरा के मंत्री थे"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, 'यह व्यंग्य है कि श्रीकृष्ण के सान्निध्य में रहकर भी वे प्रेम से वंचित रहे।', NULL, NULL, 'यह व्यंग्य है कि श्रीकृष्ण के सान्निध्य में रहकर भी वे प्रेम से वंचित रहे।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000002', 'गोपियों ने अपने मन की तुलना किस पक्षी से की है?', '{"A":"मोर","B":"हारिल पक्षी से (जो सदैव लकड़ी पकड़े रहता है)","C":"कोयल","D":"हंस"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, 'हारिल पक्षी की लकड़ी की तरह मन-वचन-कर्म से कृष्ण को पकड़ा है।', NULL, NULL, 'हारिल पक्षी की लकड़ी की तरह मन-वचन-कर्म से कृष्ण को पकड़ा है।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000003', '"पुरइनि पात रहत जल भीतर" में किस अलंकार का प्रयोग है?', '{"A":"यमक","B":"दृष्टांत / उपमा (अनुप्रास सहित)","C":"अतिशयोक्ति","D":"श्लेष"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, 'कमल के पत्ते का दृष्टांत देकर उद्धव की निर्लिप्तता दिखाई गई है।', NULL, NULL, 'कमल के पत्ते का दृष्टांत देकर उद्धव की निर्लिप्तता दिखाई गई है।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000004', 'गोपियों के अनुसार योग का संदेश सुनकर उन्हें कैसा लगता है?', '{"A":"मधु जैसा मीठा","B":"कड़वी ककड़ी के समान अरुचिकर","C":"ठंडे जल सा","D":"अमृत समान"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, '"सुनि जोग लागत है ऐसौ, ज्यौं करुई ककरी।"', NULL, NULL, '"सुनि जोग लागत है ऐसौ, ज्यौं करुई ककरी।"', 'EASY', true),
        ('10051111-0000-4000-8000-000000000005', 'गोपियाँ किससे अपने मन की बात कहना चाहती हैं?', '{"A":"अक्रूर से","B":"श्रीकृष्ण से","C":"राजा कंस से","D":"उद्धव से"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, 'वे कृष्ण के आने की आशा में तन-मन की व्यथा सह रही थीं।', NULL, NULL, 'वे कृष्ण के आने की आशा में तन-मन की व्यथा सह रही थीं।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000006', 'सूरदास के पदों की मुख्य भाषा कौन-सी है?', '{"A":"अवधी","B":"ब्रजभाषा","C":"खड़ी बोली","D":"मैथिली"}'::jsonb, 'B', 'MCQ', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 1, 'सूरदास ब्रजभाषा के सर्वश्रेष्ठ कृष्णभक्त कवि हैं।', NULL, NULL, 'सूरदास ब्रजभाषा के सर्वश्रेष्ठ कृष्णभक्त कवि हैं।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000007', 'गोपियों ने उद्धव के व्यवहार की तुलना किन दो उदाहरणों से की है?', NULL, NULL, 'VSA', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 2, 'पहला—जल के भीतर रहने वाले कमल के पत्ते (पुरइनि पात) से जिस पर पानी की बूँद नहीं ठहरती; दूसरा—तेल की गागर से जिसे जल में डुबोने पर भी उस पर पानी की एक बूँद नहीं लगती।', 'कमल का पत्ता (1M) + तेल की गागर (1M)', NULL, 'पहला—जल के भीतर रहने वाले कमल के पत्ते (पुरइनि पात) से जिस पर पानी की बूँद नहीं ठहरती; दूसरा—तेल की गागर से जिसे जल में डुबोने पर भी उस पर पानी की एक बूँद नहीं लगती।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000008', 'गोपियों के अनुसार राजा का धर्म क्या होना चाहिए?', NULL, NULL, 'VSA', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 2, 'सूरदास के अनुसार राजा का सच्चा धर्म यह है कि वह प्रजा को किसी भी प्रकार न सताए और अन्याय न होने दे, बल्कि प्रजा का हित व रक्षा करे।', 'प्रजा न सताने व हित रक्षा का भाव (2M)', NULL, 'सूरदास के अनुसार राजा का सच्चा धर्म यह है कि वह प्रजा को किसी भी प्रकार न सताए और अन्याय न होने दे, बल्कि प्रजा का हित व रक्षा करे।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000009', '"मर्यादा न लही" के माध्यम से गोपियाँ किस मर्यादा के टूटने की बात कहती हैं?', NULL, NULL, 'VSA', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 2, 'प्रेम की मर्यादा है—प्रेम के बदले प्रेम निभाना। कृष्ण ने मथुरा जाकर स्वयं न आकर योग-संदेश भेजकर प्रेम की इस मर्यादा का त्याग कर दिया।', 'प्रेम के बदले प्रेम की मर्यादा (2M)', NULL, 'प्रेम की मर्यादा है—प्रेम के बदले प्रेम निभाना। कृष्ण ने मथुरा जाकर स्वयं न आकर योग-संदेश भेजकर प्रेम की इस मर्यादा का त्याग कर दिया।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000000a', 'गोपियों के शब्दों में "व्यंग्य" (Irony) का क्या महत्व है? "हारिल की लकरी" और "राजनीति पढ़ि आए" का भावार्थ स्पष्ट कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 4, 'व्यंग्य से गोपियाँ उद्धव की नीरस ज्ञान-गर्वता पर प्रहार करती हैं। "हारिल की लकरी" एकनिष्ठ प्रेम का प्रतीक है, और "राजनीति पढ़ि आए" में यह कटाक्ष है कि अब कृष्ण चतुर राजनेता बन गए हैं।', 'व्यंग्य (1.5M) + हारिल (1.25M) + राजनीति व्यंग्य (1.25M)', 'संदर्भ: सूरदास के भ्रमरगीत प्रसंग में गोपियाँ उद्धव द्वारा लाए गए निर्गुण योग संदेश को अस्वीकार कर सगुण प्रेम की महत्ता सिद्ध करती हैं।', 'व्यंग्य से गोपियाँ उद्धव की नीरस ज्ञान-गर्वता पर प्रहार करती हैं। "हारिल की लकरी" एकनिष्ठ प्रेम का प्रतीक है, और "राजनीति पढ़ि आए" में यह कटाक्ष है कि अब कृष्ण चतुर राजनेता बन गए हैं।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000000b', 'निर्गुण योग-साधना की तुलना में गोपियों का सगुण भक्ति मार्ग क्यों श्रेष्ठ सिद्ध होता है? दो तर्क दीजिए।', NULL, NULL, 'CASE', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 4, '1. सगुण प्रेम हृदय की सहज अनुभूति है, जबकि योग-संदेश अस्थिर मन वालों के लिए कठिन व नीरस है। 2. एकनिष्ठ समर्पण मन को भटकने नहीं देता।', '2 सुस्पष्ट तर्क × 2M', NULL, '1. सगुण प्रेम हृदय की सहज अनुभूति है, जबकि योग-संदेश अस्थिर मन वालों के लिए कठिन व नीरस है। 2. एकनिष्ठ समर्पण मन को भटकने नहीं देता।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000000c', 'सूरदास के चारों पदों का सार अपने शब्दों में लिखते हुए गोपियों की वाक्पटुता और एकनिष्ठ प्रेम-भक्ति की विशेषताएँ स्पष्ट कीजिए।', NULL, NULL, 'LA', 'Hindi', 'सूरदास के पद (क्षितिज काव्य)', 5, 'चारों पदों में गोपियाँ पहले उद्धव को बड़भागी कहकर व्यंग्य करती हैं, दूसरे में मन की बात मन में रहने की पीड़ा बताती हैं, तीसरे में हारिल पक्षी और कड़वी ककड़ी के उदाहरण से योग को नकारती हैं, और चौथे में कृष्ण द्वारा राजनीति पढ़ लेने व राजधर्म की याद दिलाती हैं। वाक्पटुता, व्यंग्य व ब्रजभाषा का माधुर्य प्रमुख है।', 'चारों पदों का सार (3M) + वाक्पटुता व भाषा सौंदर्य (2M)', NULL, 'चारों पदों में गोपियाँ पहले उद्धव को बड़भागी कहकर व्यंग्य करती हैं, दूसरे में मन की बात मन में रहने की पीड़ा बताती हैं, तीसरे में हारिल पक्षी और कड़वी ककड़ी के उदाहरण से योग को नकारती हैं, और चौथे में कृष्ण द्वारा राजनीति पढ़ लेने व राजधर्म की याद दिलाती हैं। वाक्पटुता, व्यंग्य व ब्रजभाषा का माधुर्य प्रमुख है।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000000d', 'सीता स्वयंवर में शिव धनुष किसने तोड़ा था?', '{"A":"लक्ष्मण","B":"श्रीराम","C":"जनक","D":"विश्वामित्र"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'श्रीराम के छूते ही पुराना शिव धनुष टूट गया।', NULL, NULL, 'श्रीराम के छूते ही पुराना शिव धनुष टूट गया।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000000e', 'लक्ष्मण ने धनुष टूटने का कारण व्यंग्य से क्या बताया?', '{"A":"धनुष लोहे का था","B":"बचपन में हमने अनेक धनुहियाँ तोड़ीं; यह तो पुराना व जीर्ण था, छूते ही टूट गया","C":"आँधी चली थी","D":"परशुराम ने तोड़ा"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'बचपन में अनेक धनुहियाँ तोड़ने की तुलना कर व्यंग्य किया।', NULL, NULL, 'बचपन में अनेक धनुहियाँ तोड़ने की तुलना कर व्यंग्य किया।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000000f', 'परशुराम ने किसके वध से धरती को अनेक बार क्षत्रियों से रहित करने की बात कही?', '{"A":"रावण","B":"सहस्रबाहु आदि राजाओं","C":"कंस","D":"बाली"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'सहस्रबाहु को मारकर भुजाएँ काटने का उल्लेख किया।', NULL, NULL, 'सहस्रबाहु को मारकर भुजाएँ काटने का उल्लेख किया।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000010', '"गाधिसूनु" शब्द का प्रयोग तुलसीदास ने किसके लिए किया है?', '{"A":"परशुराम","B":"विश्वामित्र (गाधि के पुत्र)","C":"जनक","D":"दशरथ"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'गाधिसूनु = ऋषि विश्वामित्र।', NULL, NULL, 'गाधिसूनु = ऋषि विश्वामित्र।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000011', 'इस संवाद में श्रीराम का स्वभाव कैसा दिखाया गया है?', '{"A":"अत्यंत क्रोधी","B":"विनम्र, शांत, शीलवान और मर्यादापुरुषोत्तम","C":"डरपोक","D":"अहंकारी"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'राम स्वयं को परशुराम का सेवक बताकर विनम्रता से शांत करते हैं।', NULL, NULL, 'राम स्वयं को परशुराम का सेवक बताकर विनम्रता से शांत करते हैं।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000012', 'तुलसीदास के "राम-लक्ष्मण-परशुराम संवाद" की भाषा व छंद हैं:', '{"A":"ब्रज व कवित्त","B":"अवधी भाषा व दोहा-चौपाई छंद","C":"खड़ी बोली व मुक्त छंद","D":"संस्कृत व श्लोक"}'::jsonb, 'B', 'MCQ', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 1, 'रामचरितमानस का यह अंश अवधी भाषा, दोहा-चौपाई में है।', NULL, NULL, 'रामचरितमानस का यह अंश अवधी भाषा, दोहा-चौपाई में है।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000013', 'परशुराम के क्रोध करने पर राम ने धनुष टूटने के लिए कौन-से शांत तर्क दिए?', NULL, NULL, 'VSA', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 2, 'राम ने अत्यंत विनम्र होकर कहा कि शिव धनुष तोड़ने वाला कोई आपका ही सेवक (दास) होगा, और आज्ञा माँगकर क्रोध शांत करने का प्रयास किया।', 'सेवक भाव व विनम्रता (2M)', NULL, 'राम ने अत्यंत विनम्र होकर कहा कि शिव धनुष तोड़ने वाला कोई आपका ही सेवक (दास) होगा, और आज्ञा माँगकर क्रोध शांत करने का प्रयास किया।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000014', '"इहाँ कुम्हड़बतिया कोउ नाहीं" कहकर लक्ष्मण क्या सिद्ध करना चाहते हैं?', NULL, NULL, 'VSA', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 2, 'लक्ष्मण कहना चाहते हैं कि हम कोई छुईमुई/काशीफल के कच्चे फल नहीं हैं जो आपकी तर्जनी उँगली दिखाने से ही मुरझाकर डर जाएँगे — हम भी वीर योद्धा हैं।', 'साहस व निर्भीकता का भाव (2M)', NULL, 'लक्ष्मण कहना चाहते हैं कि हम कोई छुईमुई/काशीफल के कच्चे फल नहीं हैं जो आपकी तर्जनी उँगली दिखाने से ही मुरझाकर डर जाएँगे — हम भी वीर योद्धा हैं।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000015', 'साहस और शक्ति के साथ विनम्रता क्यों आवश्यक है? राम और लक्ष्मण के व्यवहार से समझाइए।', NULL, NULL, 'VSA', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 2, 'केवल शक्ति या क्रोध से विवाद बढ़ता है (लक्ष्मण-परशुराम संवाद की तरह), जबकि शक्ति के साथ विनम्रता (श्रीराम का व्यवहार) बड़े से बड़े संकट व क्रोध को शांत कर देती है।', 'तर्क + दोनों का तुलनात्मक उदाहरण (2M)', NULL, 'केवल शक्ति या क्रोध से विवाद बढ़ता है (लक्ष्मण-परशुराम संवाद की तरह), जबकि शक्ति के साथ विनम्रता (श्रीराम का व्यवहार) बड़े से बड़े संकट व क्रोध को शांत कर देती है।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000016', '(i) विश्वामित्र मन ही मन क्यों मुस्कुराए ("मुनिहि हरियरे सूझ")? (ii) "अयमय खाँड न ऊखमय" का आशय लिखिए। (iii) लक्ष्मण ने परशुराम को बार-बार किस आभूषण/शास्त्र की याद दिलाई? (iv) भाव-सौंदर्य बताइए।', NULL, NULL, 'CASE', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 4, '(i) परशुराम राम-लक्ष्मण को साधारण बालक समझ रहे थे ("सावन के अंधे को हरा ही हरा सूझना")। (ii) ये लोहे (फौलाद) की बनी तलवार हैं, गन्ने के रस की खाँड़ (चीनी) नहीं जो मुँह में घुल जाएँ। (iii) ब्राह्मण व भृगुवंशी होने पर हाथ न उठाने की बात। (iv) वीर और हास्य/व्यंग्य रस का अद्भुत संगम।', '4 × 1M = 4M', 'प्रसंग: परशुराम के बार-बार फरसा दिखाकर बालक-वध की धमकी देने पर ऋषि विश्वामित्र मन में हँसते हैं कि मुनि को हर ओर हरा ही हरा दिख रहा है।', '(i) परशुराम राम-लक्ष्मण को साधारण बालक समझ रहे थे ("सावन के अंधे को हरा ही हरा सूझना")। (ii) ये लोहे (फौलाद) की बनी तलवार हैं, गन्ने के रस की खाँड़ (चीनी) नहीं जो मुँह में घुल जाएँ। (iii) ब्राह्मण व भृगुवंशी होने पर हाथ न उठाने की बात। (iv) वीर और हास्य/व्यंग्य रस का अद्भुत संगम।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000017', 'लक्ष्मण ने वीर योद्धा की क्या-क्या विशेषताएँ बताई हैं? पाठ के आधार पर चार बिंदु लिखिए।', NULL, NULL, 'CASE', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 4, '1. शूरवीर युद्धभूमि में शौर्य दिखाते हैं, अपनी प्रशंसा स्वयं नहीं करते। 2. रणभूमि में शत्रु के सामने केवल कायराना बातें नहीं करते। 3. ब्राह्मण, गाय, देवता और भक्त पर वीरता नहीं दिखाते। 4. धैर्यवान और क्षोभरहित होते हैं।', '4 विशेषताएँ × 1M = 4M', NULL, '1. शूरवीर युद्धभूमि में शौर्य दिखाते हैं, अपनी प्रशंसा स्वयं नहीं करते। 2. रणभूमि में शत्रु के सामने केवल कायराना बातें नहीं करते। 3. ब्राह्मण, गाय, देवता और भक्त पर वीरता नहीं दिखाते। 4. धैर्यवान और क्षोभरहित होते हैं।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000018', 'परशुराम के क्रोध से लेकर श्रीराम की विनम्रता और लक्ष्मण के व्यंग्य तक इस पूरे प्रसंग की नाटकीयता एवं संवाद-कला पर एक निबंधात्मक उत्तर लिखिए।', NULL, NULL, 'LA', 'Hindi', 'राम-लक्ष्मण-परशुराम संवाद (तुलसीदास)', 5, 'रंगमंचीय नाटकीयता: धनुष टूटने की टंकार से परशुराम का क्रोधपूर्ण आगमन, राम के "नाथ संभुधनु भंजनिहारा..." जैसे शांत वचन, लक्ष्मण के तीखे कटाक्ष, विश्वामित्र का मन-ही-मन हँसना और अंत में जल के समान शीतल राम-वचनों से क्रोधाग्नि बुझना। अवधी भाषा, अनुप्रास व रूपक अलंकार तथा वीर-रौद्र-हास्य रसों का सुंदर समन्वय।', 'चरित्र विश्लेषण (3M) + भाषा-शैली व काव्य सौंदर्य (2M)', NULL, 'रंगमंचीय नाटकीयता: धनुष टूटने की टंकार से परशुराम का क्रोधपूर्ण आगमन, राम के "नाथ संभुधनु भंजनिहारा..." जैसे शांत वचन, लक्ष्मण के तीखे कटाक्ष, विश्वामित्र का मन-ही-मन हँसना और अंत में जल के समान शीतल राम-वचनों से क्रोधाग्नि बुझना। अवधी भाषा, अनुप्रास व रूपक अलंकार तथा वीर-रौद्र-हास्य रसों का सुंदर समन्वय।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000019', 'जयशंकर प्रसाद ने अपनी आत्मकथा लिखने से क्यों इनकार किया ("आत्मकथ्य")?', '{"A":"समय नहीं था","B":"उन्हें अपना जीवन सामान्य, दुर्बलताओं से भरा लगा व वे मित्रों के छल उजागर नहीं करना चाहते थे","C":"प्रकाशन बंद था","D":"वे हिंदी नहीं जानते थे"}'::jsonb, 'B', 'MCQ', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 1, 'अपने सरल स्वभाव और निजी दुखों को उपहास का पात्र नहीं बनाना चाहते थे।', NULL, NULL, 'अपने सरल स्वभाव और निजी दुखों को उपहास का पात्र नहीं बनाना चाहते थे।', 'EASY', true),
