        ('10051111-0000-4000-8000-00000000001b', '"अट नहीं रही है" कविता में किस महीने की मादक सुंदरता का वर्णन है?', '{"A":"सावन","B":"फागुन (वसंत)","C":"पूस","D":"माघ"}'::jsonb, 'B', 'MCQ', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 1, 'फागुन मास की शोभा धरती में समा नहीं पा रही है।', NULL, NULL, 'फागुन मास की शोभा धरती में समा नहीं पा रही है।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000001c', '"यह दंतुरित मुसकान" में शिशु की मुसकान किस में भी प्राण डाल देती है?', '{"A":"केवल पक्षियों में","B":"मृतक में भी जान डाल देती है तथा कठोर पाषाण को पिघला देती है","C":"पेड़ों में","D":"बादलों में"}'::jsonb, 'B', 'MCQ', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 1, 'शिशु की निश्छल मुसकान जड़-चेतन सबको सजीव कर देती है।', NULL, NULL, 'शिशु की निश्छल मुसकान जड़-चेतन सबको सजीव कर देती है।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000001d', 'नागार्जुन ने "फ़सल" को किसका जादू कहा है?', '{"A":"केवल किसान का","B":"नदियों के पानी, लाखों हाथों के स्पर्श, मिट्टी के गुण-धर्म, सूरज की किरणों व हवा की थिरकन का रूपांतरण","C":"रासायनिक खाद का","D":"केवल वर्षा का"}'::jsonb, 'B', 'MCQ', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 1, 'प्रकृति और मानव श्रम का सामूहिक परिणाम है फ़सल।', NULL, NULL, 'प्रकृति और मानव श्रम का सामूहिक परिणाम है फ़सल।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000001e', 'मंगलेश डबराल की "संगतकार" कविता में संगतकार कौन होता है?', '{"A":"मुख्य गायक के पीछे मुख्य स्वर को बल व सहारा देने वाला सहायक गायक/वाद्यकार","B":"दर्शक","C":"प्रबंधक","D":"आलोचक"}'::jsonb, 'A', 'MCQ', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 1, 'मुख्य गायक के भटकने या स्वर गिरने पर संभालने वाला सच्चा सहयोगी।', NULL, NULL, 'मुख्य गायक के भटकने या स्वर गिरने पर संभालने वाला सच्चा सहयोगी।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000001f', '"मिला कहाँ वह सुख जिसका मैं स्वप्न देखकर जाग गया" — इस पंक्ति में प्रसाद जी का क्या दर्द छिपा है?', NULL, NULL, 'VSA', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 2, 'कवि ने सुखी जीवन और प्रेम के सुंदर स्वप्न देखे थे, पर आलिंगन में आने से पहले ही वे सुख के क्षण छिटक गए — अधूरी इच्छाओं की यही पीड़ा व्यक्त हुई है।', 'स्वप्न भंग व अधूरे सुख की पीड़ा (2M)', NULL, 'कवि ने सुखी जीवन और प्रेम के सुंदर स्वप्न देखे थे, पर आलिंगन में आने से पहले ही वे सुख के क्षण छिटक गए — अधूरी इच्छाओं की यही पीड़ा व्यक्त हुई है।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000020', '"उत्साह" कविता में कवि ने बादलों से "गरजो!" का आह्वान क्यों किया है, "बरसो!" क्यों नहीं?', NULL, NULL, 'VSA', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 2, 'कवि जनमानस में जड़ता तोड़कर नया जोश, पौरुष और क्रांति की चेतना जगाना चाहते हैं; गरजना सक्रिय परिवर्तन व उत्साह का प्रतीक है।', 'क्रांति व चेतना का प्रतीक (2M)', NULL, 'कवि जनमानस में जड़ता तोड़कर नया जोश, पौरुष और क्रांति की चेतना जगाना चाहते हैं; गरजना सक्रिय परिवर्तन व उत्साह का प्रतीक है।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000021', 'संगतकार द्वारा मुख्य गायक से अपना स्वर जानबूझकर नीचा रखने को "मनुष्यता" क्यों कहा गया है?', NULL, NULL, 'VSA', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 2, 'अपनी योग्यता होते हुए भी अहंकार त्यागकर मुख्य कलाकार के सम्मान व सफलता की रक्षा करना उसकी विनम्र मानवीय संवेदनशीलता को दर्शाता है।', 'विनम्रता व सहयोग की भावना (2M)', NULL, 'अपनी योग्यता होते हुए भी अहंकार त्यागकर मुख्य कलाकार के सम्मान व सफलता की रक्षा करना उसकी विनम्र मानवीय संवेदनशीलता को दर्शाता है।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000022', '(i) "बाँस और बबूल" तथा "कमल के तालाब" में क्या अंतर दिखाया गया है? (ii) शिशु पहली बार कवि को कैसे पहचानता है? (iii) कवि ने शिशु की माँ को धन्य क्यों कहा है? (iv) "धुली-धूसर तुम्हारे गात" का अर्थ लिखिए।', NULL, NULL, 'CASE', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 4, '(i) कठोर हृदय (बाँस-बबूल) भी शेफालिका के फूलों की तरह कोमल झरने लगते हैं; कमल झोंपड़ी में खिल उठे। (ii) माँ के माध्यम ("धन्य तुम, माँ भी तुम्हारी धन्य") और अनिमिष देखने से। (iii) माँ ने ही प्रवासी पिता और शिशु के बीच परिचय की मधुर कड़ी जोड़ी। (iv) धूल से सना हुआ तुम्हारा कोमल शरीर।', '4 × 1M = 4M', 'प्रसंग: लंबे प्रवास के बाद लौटे कवि नागार्जुन नन्हें शिशु के नए निकले दाँतों की मुसकान देखकर चकित हो उठते हैं।', '(i) कठोर हृदय (बाँस-बबूल) भी शेफालिका के फूलों की तरह कोमल झरने लगते हैं; कमल झोंपड़ी में खिल उठे। (ii) माँ के माध्यम ("धन्य तुम, माँ भी तुम्हारी धन्य") और अनिमिष देखने से। (iii) माँ ने ही प्रवासी पिता और शिशु के बीच परिचय की मधुर कड़ी जोड़ी। (iv) धूल से सना हुआ तुम्हारा कोमल शरीर।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000023', '"फ़सल" कविता हमें प्रकृति और कृषक के प्रति किस प्रकार कृतज्ञ होना सिखाती है?', NULL, NULL, 'CASE', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 4, 'यह कविता सिखाती है कि अन्न केवल किसी एक व्यक्ति की उपज नहीं, बल्कि लाखों किसानों के पसीने, विभिन्न मिट्टियों के पोषण, नदियों के जल, सूर्य की ऊष्मा और हवा के सामूहिक सहयोग का प्रसाद है — अतः हमें अन्न का सम्मान और श्रमजीवियों का आदर करना चाहिए।', 'प्रकृति के तत्व (2M) + मानव श्रम व कृतज्ञता संदेश (2M)', NULL, 'यह कविता सिखाती है कि अन्न केवल किसी एक व्यक्ति की उपज नहीं, बल्कि लाखों किसानों के पसीने, विभिन्न मिट्टियों के पोषण, नदियों के जल, सूर्य की ऊष्मा और हवा के सामूहिक सहयोग का प्रसाद है — अतः हमें अन्न का सम्मान और श्रमजीवियों का आदर करना चाहिए।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000024', 'मंगलेश डबराल की "संगतकार" कविता के आधार पर स्पष्ट कीजिए कि समाज, कला और राष्ट्र निर्माण में नेपथ्य (पर्दे के पीछे) रहकर कार्य करने वाले सहयोगियों का कितना बड़ा योगदान होता है।', NULL, NULL, 'LA', 'Hindi', 'आत्मकथ्य, उत्साह व यह दंतुरित मुसकान', 5, 'सफलता के शिखर पर केवल मुख्य नायक दिखता है, पर जब उसका स्वर टूटता है, उत्साह मंद पड़ता है या वह अंतरे की जटिल तान में भटकता है, तब संगतकार अपनी पूरी क्षमता को संयत रखकर उसे संभालता है। अपनी आवाज दबाकर दूसरों को ऊँचा उठाना कायरता नहीं, अपितु सर्वोच्च मानवीय गुण व सामूहिक सिद्धि का आधार है।', 'कविता के प्रसंग (3M) + सामाजिक महत्व व निष्कर्ष (2M)', NULL, 'सफलता के शिखर पर केवल मुख्य नायक दिखता है, पर जब उसका स्वर टूटता है, उत्साह मंद पड़ता है या वह अंतरे की जटिल तान में भटकता है, तब संगतकार अपनी पूरी क्षमता को संयत रखकर उसे संभालता है। अपनी आवाज दबाकर दूसरों को ऊँचा उठाना कायरता नहीं, अपितु सर्वोच्च मानवीय गुण व सामूहिक सिद्धि का आधार है।', 'HARD', true),
