        ('10051111-0000-4000-8000-000000000028', 'अंतिम बार जब हालदार साहब चौराहे से गुज़रे तो नेताजी की आँखों पर कौन-सा चश्मा लगा था?', '{"A":"सोने का","B":"सरकंडे से बना छोटा-सा चश्मा (बच्चों द्वारा बनाया)","C":"काले काँच का","D":"कोई चश्मा नहीं"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 1, 'बच्चों द्वारा लगाया सरकंडे का चश्मा भावी पीढ़ी में जीवित देशभक्ति का प्रतीक था।', NULL, NULL, 'बच्चों द्वारा लगाया सरकंडे का चश्मा भावी पीढ़ी में जीवित देशभक्ति का प्रतीक था।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000029', 'पानवाले के अनुसार कैप्टन की मृत्यु का हालदार साहब पर क्या प्रभाव पड़ा?', '{"A":"वे हँस पड़े","B":"वे उदास हो गए और कुछ दिन चौराहे पर पान न खाने का सोचा","C":"वे नाराज हुए","D":"उन्हें कोई फर्क न पड़ा"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 1, 'कैप्टन के न रहने से उन्हें लगा कि अब मूर्ति बिना चश्मे की रहेगी।', NULL, NULL, 'कैप्टन के न रहने से उन्हें लगा कि अब मूर्ति बिना चश्मे की रहेगी।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000002a', 'इस कहानी का केंद्रीय संदेश क्या है?', '{"A":"मूर्तियाँ महँगी होनी चाहिए","B":"देशभक्ति केवल सीमा पर लड़ने तक सीमित नहीं, छोटे-छोटे नागरिक व बच्चे भी अपनी-अपनी तरह देशप्रेम निभाते हैं","C":"चश्मा व्यापार बढ़ाना","D":"कस्बे छोटे होते हैं"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 1, 'हर नागरिक अपने छोटे योगदान से देशभक्ति निभा सकता है।', NULL, NULL, 'हर नागरिक अपने छोटे योगदान से देशभक्ति निभा सकता है।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000002b', 'नेताजी की मूर्ति की आँखों पर असली चश्मा न होने का क्या संभावित कारण पाठ में बताया गया?', NULL, NULL, 'VSA', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 2, 'शायद कम बजट व समय की कमी के कारण मूर्तिकार मोतीलाल चश्मा बनाना भूल गया, या पारदर्शी पत्थर का चश्मा बनाकर पहनाने पर वह टूट गया होगा।', 'दोनों संभावित कारण (2M)', NULL, 'शायद कम बजट व समय की कमी के कारण मूर्तिकार मोतीलाल चश्मा बनाना भूल गया, या पारदर्शी पत्थर का चश्मा बनाकर पहनाने पर वह टूट गया होगा।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000002c', 'सेनानी न होते हुए भी चश्मेवाले को लोग कैप्टन क्यों कहते थे?', NULL, NULL, 'VSA', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 2, 'उसका कद-काठी कमजोर व लँगड़ा जरूर था, परंतु नेताजी के प्रति अपार श्रद्धा देखकर और उन्हें बिना चश्मे के देख आहत होकर बार-बार चश्मा पहनाने की देशभक्ति ने उसे जनमानस में "कैप्टन" बना दिया।', 'देशभक्ति व श्रद्धा का कारण (2M)', NULL, 'उसका कद-काठी कमजोर व लँगड़ा जरूर था, परंतु नेताजी के प्रति अपार श्रद्धा देखकर और उन्हें बिना चश्मे के देख आहत होकर बार-बार चश्मा पहनाने की देशभक्ति ने उसे जनमानस में "कैप्टन" बना दिया।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000002d', 'पानवाले का रेखाचित्र अपने शब्दों में प्रस्तुत कीजिए।', NULL, NULL, 'VSA', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 2, 'पानवाला काला, मोटा और खुशमिजाज व्यक्ति था; उसकी तोंद थिरकती थी और मुँह में हमेशा पान ठुँसे होने के कारण बात करने पर लाल-काली बत्तीसी दिखती थी, पर वह भावुक भी था (कैप्टन की मृत्यु पर आँखें पोंछीं)।', 'शारीरिक व संवेदनशील रूप (2M)', NULL, 'पानवाला काला, मोटा और खुशमिजाज व्यक्ति था; उसकी तोंद थिरकती थी और मुँह में हमेशा पान ठुँसे होने के कारण बात करने पर लाल-काली बत्तीसी दिखती थी, पर वह भावुक भी था (कैप्टन की मृत्यु पर आँखें पोंछीं)।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000002e', '(i) हालदार साहब पहले मायूस क्यों हो गए थे? (ii) फिर उन्होंने ड्राइवर से अचानक जीप रोकने को क्यों कहा? (iii) मूर्ति पर सरकंडे का चश्मा किसने लगाया होगा? (iv) यह अंत हमें क्या आशा देता है?', NULL, NULL, 'CASE', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 4, '(i) कैप्टन की मृत्यु के बाद उन्हें लगा कस्बे में अब कोई नेताजी की मूर्ति पर चश्मा नहीं लगाएगा। (ii) मूर्ति पर सरकंडे का चश्मा लगा देखकर भावुक हो उठे। (iii) कस्बे के किसी देशभक्त बच्चे ने। (iv) भावी पीढ़ी के हृदय में भी देशभक्ति की लौ सुरक्षित व जीवंत है।', '4 × 1M = 4M', 'प्रसंग: कैप्टन के निधन की खबर सुनने के कई दिनों बाद हालदार साहब आँखें बंद रखने का निश्चय कर कस्बे से निकल रहे थे, तभी अचानक जीप रोकने चिल्ला उठे।', '(i) कैप्टन की मृत्यु के बाद उन्हें लगा कस्बे में अब कोई नेताजी की मूर्ति पर चश्मा नहीं लगाएगा। (ii) मूर्ति पर सरकंडे का चश्मा लगा देखकर भावुक हो उठे। (iii) कस्बे के किसी देशभक्त बच्चे ने। (iv) भावी पीढ़ी के हृदय में भी देशभक्ति की लौ सुरक्षित व जीवंत है।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000002f', 'क्या किसी ग्राहक को पसंद आया चश्मा मूर्ति से उतारकर देने में कैप्टन की कोई स्वार्थ-भावना थी? तर्कसहित स्पष्ट कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 4, 'नहीं, इसमें स्वार्थ नहीं था। वह अत्यंत गरीब फेरीवाला था जिसके पास दुकान तक न थी; सीमित पूँजी में वह तुरंत दूसरा चश्मा मूर्ति को पहनाकर नेताजी से क्षमा माँग लेता था ताकि मूर्ति की शोभा बनी रहे।', 'गरीबी व विवशता (2M) + निस्वार्थ आदर (2M)', NULL, 'नहीं, इसमें स्वार्थ नहीं था। वह अत्यंत गरीब फेरीवाला था जिसके पास दुकान तक न थी; सीमित पूँजी में वह तुरंत दूसरा चश्मा मूर्ति को पहनाकर नेताजी से क्षमा माँग लेता था ताकि मूर्ति की शोभा बनी रहे।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000030', '"नेताजी का चश्मा" कहानी के माध्यम से स्वयं प्रकाश ने देशभक्ति और नागरिक कर्तव्य की जो परिभाषा दी है, उसे कैप्टन, पानवाले, हालदार साहब और कस्बे के बच्चों के संदर्भ में स्पष्ट कीजिए।', NULL, NULL, 'LA', 'Hindi', 'नेताजी का चश्मा (स्वयं प्रकाश)', 5, 'कहानी बताती है कि देश निर्माण में छोटे लोगों और बच्चों की भूमिका भी अमूल्य है। कैप्टन अपने सीमित साधनों से देशनायकों का सम्मान जीवित रखता है; हालदार साहब जैसी संवेदनशील नागरिक पीढ़ी इस भाव को पहचानती है; पानवाला पहले उपहास करता है पर भीतर से संवेदनशील है; और अंततः बच्चों का सरकंडे का चश्मा भविष्य के प्रति आश्वस्त करता है।', '4 पात्रों की भूमिका (3.5M) + केंद्रीय संदेश (1.5M)', NULL, 'कहानी बताती है कि देश निर्माण में छोटे लोगों और बच्चों की भूमिका भी अमूल्य है। कैप्टन अपने सीमित साधनों से देशनायकों का सम्मान जीवित रखता है; हालदार साहब जैसी संवेदनशील नागरिक पीढ़ी इस भाव को पहचानती है; पानवाला पहले उपहास करता है पर भीतर से संवेदनशील है; और अंततः बच्चों का सरकंडे का चश्मा भविष्य के प्रति आश्वस्त करता है।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000031', 'बालगोबिन भगत गृहस्थ होते हुए भी "साधु" क्यों कहलाते थे?', '{"A":"वे जंगल में रहते थे","B":"वे कबीर को \"साहब\" मानकर सत्य, अहिंसा, निस्वार्थ सेवा व संतोष का पालन करते थे","C":"वे भीख माँगते थे","D":"वे जटाएँ रखते थे"}'::jsonb, 'B', 'MCQ', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 1, 'सच्ची साधुता वेशभूषा से नहीं, आचरण व चरित्र की शुद्धता से होती है।', NULL, NULL, 'सच्ची साधुता वेशभूषा से नहीं, आचरण व चरित्र की शुद्धता से होती है।', 'EASY', true),
