        ('10051111-0000-4000-8000-000000000037', 'खेतीबारी से जुड़े गृहस्थ बालगोबिन भगत अपनी किन चारित्रिक विशेषताओं के कारण साधु कहलाते थे?', NULL, NULL, 'VSA', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 2, 'कभी झूठ न बोलना, खरा व्यवहार रखना, बिना पूछे किसी की वस्तु न छूना, शौच आदि के लिए किसी के खेत का उपयोग न करना और सब कुछ साहब (कबीर) का मानकर प्रसाद-मात्र ग्रहण करना।', 'कोई 3–4 चारित्रिक गुण (2M)', NULL, 'कभी झूठ न बोलना, खरा व्यवहार रखना, बिना पूछे किसी की वस्तु न छूना, शौच आदि के लिए किसी के खेत का उपयोग न करना और सब कुछ साहब (कबीर) का मानकर प्रसाद-मात्र ग्रहण करना।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000038', 'भगत की पुत्रवधू उन्हें अकेले छोड़कर क्यों नहीं जाना चाहती थी?', NULL, NULL, 'VSA', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 2, 'वह भगत के बुढ़ापे की चिंता करती थी कि उनके बीमार पड़ने पर कौन चुल्लू भर पानी देगा और कौन उनके लिए रोटी पकाएगा।', 'सेवा व बुढ़ापे की चिंता (2M)', NULL, 'वह भगत के बुढ़ापे की चिंता करती थी कि उनके बीमार पड़ने पर कौन चुल्लू भर पानी देगा और कौन उनके लिए रोटी पकाएगा।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000039', 'आषाढ़ की रिमझिम फुहारों में भगत का संगीत समूचे गाँव को किस प्रकार झंकृत कर देता था?', NULL, NULL, 'VSA', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 2, 'कीचड़ से लथपथ धान की रोपनी करते हुए भगत के कंठ से फूटा स्वर बच्चों, हलवाहों के पैर और औरतों के होंठों को स्वत: लय व उत्साह से भर देता था।', 'संगीत का जादू व श्रम का उत्सव (2M)', NULL, 'कीचड़ से लथपथ धान की रोपनी करते हुए भगत के कंठ से फूटा स्वर बच्चों, हलवाहों के पैर और औरतों के होंठों को स्वत: लय व उत्साह से भर देता था।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000003a', '(i) भगत जी हर वर्ष गंगा स्नान के लिए पैदल क्यों जाते थे? (ii) रास्ते में उपवास और घर लौटकर ही खाने के पीछे क्या नियम था? (iii) उनकी मृत्यु कैसे हुई? (iv) "मोह और प्रेम में अंतर" उनके चरित्र से कैसे सिद्ध होता है?', NULL, NULL, 'CASE', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 4, '(i) संत-समागम और लोक-दर्शन के लिए (स्नान के आडंबर से अधिक)। (ii) साधु को संबल लेने और गृहस्थ होकर भिक्षा न माँगने का नियम। (iii) बुखार और जर्जर शरीर के बावजूद नियमित स्नान-गीत निभाते हुए शांत निधन। (iv) मोह स्वार्थ में बाँधता है, जबकि प्रेम पतोहू को दूसरा विवाह कर सुखी देखने की त्याग-भावना सिखाता है।', '4 × 1M = 4M', 'प्रसंग: बुढ़ापे में भी बालगोबिन भगत ने अपनी प्रभातियाँ, कार्तिक-फाल्गुन के गीत और तीस कोस दूर गंगा स्नान का नियम जीवन के अंतिम दिन तक नहीं छोड़ा।', '(i) संत-समागम और लोक-दर्शन के लिए (स्नान के आडंबर से अधिक)। (ii) साधु को संबल लेने और गृहस्थ होकर भिक्षा न माँगने का नियम। (iii) बुखार और जर्जर शरीर के बावजूद नियमित स्नान-गीत निभाते हुए शांत निधन। (iv) मोह स्वार्थ में बाँधता है, जबकि प्रेम पतोहू को दूसरा विवाह कर सुखी देखने की त्याग-भावना सिखाता है।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000003b', 'पाठ के आधार पर सिद्ध कीजिए कि बालगोबिन भगत सामाजिक रूढ़ियों के प्रबल विरोधी और सच्चे समाज-सुधारक थे।', NULL, NULL, 'CASE', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 4, '1. मृत्यु को विरह-मिलन का उत्सव मानकर आडंबरपूर्ण शोक का विरोध किया। 2. पुत्र की चिता को पतोहू से मुखाग्नि दिलाकर लैंगिक भेदभाव तोड़ा। 3. पतोहू का पुनर्विवाह करवाकर विधवा जीवन की कुप्रथा का प्रतिकार किया।', '3 ठोस उदाहरण + निष्कर्ष (4M)', NULL, '1. मृत्यु को विरह-मिलन का उत्सव मानकर आडंबरपूर्ण शोक का विरोध किया। 2. पुत्र की चिता को पतोहू से मुखाग्नि दिलाकर लैंगिक भेदभाव तोड़ा। 3. पतोहू का पुनर्विवाह करवाकर विधवा जीवन की कुप्रथा का प्रतिकार किया।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000003c', 'बालगोबिन भगत का व्यक्तित्व और जीवन-दर्शन आज के भौतिकवादी व रूढ़िग्रस्त समाज के लिए क्यों प्रासंगिक है? पाठ की मुख्य घटनाओं सहित उत्तर दीजिए।', NULL, NULL, 'LA', 'Hindi', 'बालगोबिन भगत (रामवृक्ष बेनीपुरी)', 5, 'आज दिखावे, लालच, जाति-पाति और लैंगिक असमानता के युग में भगत का सादगीपूर्ण जीवन (मठ में फसल सौंपना, बिना लालच श्रम करना), प्रकृति व संगीत से जुड़ाव (आषाढ़-कार्तिक के गीत), और पतोहू को मुखाग्नि व पुनर्विवाह का अधिकार दिलाना अत्यंत प्रगतिशील व प्रेरक है। वे सिखाते हैं कि धर्म बाहरी आडंबर नहीं, मानवीय करुणा व सत्यनिष्ठा है।', 'जीवन-दर्शन व घटनाएँ (3M) + आधुनिक प्रासंगिकता (2M)', NULL, 'आज दिखावे, लालच, जाति-पाति और लैंगिक असमानता के युग में भगत का सादगीपूर्ण जीवन (मठ में फसल सौंपना, बिना लालच श्रम करना), प्रकृति व संगीत से जुड़ाव (आषाढ़-कार्तिक के गीत), और पतोहू को मुखाग्नि व पुनर्विवाह का अधिकार दिलाना अत्यंत प्रगतिशील व प्रेरक है। वे सिखाते हैं कि धर्म बाहरी आडंबर नहीं, मानवीय करुणा व सत्यनिष्ठा है।', 'HARD', true),
