        ('10051111-0000-4000-8000-000000000040', 'मन्नू भंडारी के पिता इंदौर से अजमेर आकर आर्थिक रूप से टूटने के बाद किस स्वभाव के हो गए थे?', '{"A":"अत्यंत शांत","B":"शक्की, क्रोधी और अहंवादी (बच्चों पर क्रोध उतारने वाले)","C":"दानवीर","D":"उदासीन"}'::jsonb, 'B', 'MCQ', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 1, 'आर्थिक विफलता और विश्वासघातों ने उन्हें शक्की व गुस्सैल बना दिया।', NULL, NULL, 'आर्थिक विफलता और विश्वासघातों ने उन्हें शक्की व गुस्सैल बना दिया।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000041', 'मन्नू भंडारी के जीवन को दिशा देने वाली उनकी किस हिंदी प्राध्यापिका का नाम पाठ में प्रमुख है?', '{"A":"सरोजनी जी","B":"शीला अग्रवाल","C":"महादेवी वर्मा","D":"सुभद्रा कुमारी"}'::jsonb, 'B', 'MCQ', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 1, 'शीला अग्रवाल ने उन्हें चुनिंदा साहित्य पढ़ाकर वैचारिक व सामाजिक संघर्ष से जोड़ा।', NULL, NULL, 'शीला अग्रवाल ने उन्हें चुनिंदा साहित्य पढ़ाकर वैचारिक व सामाजिक संघर्ष से जोड़ा।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000042', 'जब प्रिंसिपल ने मन्नू के पिता को आंदोलन की शिकायत करने बुलाया तो अंत में पिता की प्रतिक्रिया क्या हुई?', '{"A":"उन्हें घर में बंद कर दिया","B":"लड़कियों और पूरे कॉलेज पर बेटी के प्रभाव को सुनकर वे क्रोध के बजाय गर्व से भर उठे","C":"कॉलेज छुड़वा दिया","D":"शहर छोड़ दिया"}'::jsonb, 'B', 'MCQ', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 1, '"यह लड़की तो पूरे देश की आवाज़ बन गई है!" — गर्व से गदगद हुए।', NULL, NULL, '"यह लड़की तो पूरे देश की आवाज़ बन गई है!" — गर्व से गदगद हुए।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000043', 'नवाब साहब द्वारा खीरे सूँघकर फेंक देने के बाद लेखक के मन में "नई कहानी" को लेकर क्या व्यंग्य विचार उठा?', NULL, NULL, 'VSA', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 2, 'लेखक ने सोचा कि जब बिना खीरा खाए केवल सूँघने और डकार लेने से पेट भर सकता है, तो बिना घटना, पात्र और विचार के भी "नई कहानी" क्यों नहीं लिखी जा सकती!', 'यशपाल का साहित्यिक व्यंग्य (2M)', NULL, 'लेखक ने सोचा कि जब बिना खीरा खाए केवल सूँघने और डकार लेने से पेट भर सकता है, तो बिना घटना, पात्र और विचार के भी "नई कहानी" क्यों नहीं लिखी जा सकती!', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000044', 'लेखिका मन्नू भंडारी के व्यक्तित्व पर उनके पिता के किन सकारात्मक व नकारात्मक गुणों का प्रभाव पड़ा?', NULL, NULL, 'VSA', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 2, 'सकारात्मक: देश-समाज की घटनाओं, बहसों और राजनीतिक जागरूकता का वातावरण मिला। नकारात्मक: गोरी-सुंदर बड़ी बहन सुशीला से लगातार तुलना होने से मन्नू में हीन-भावना घर कर गई।', '1M सकारात्मक + 1M नकारात्मक', NULL, 'सकारात्मक: देश-समाज की घटनाओं, बहसों और राजनीतिक जागरूकता का वातावरण मिला। नकारात्मक: गोरी-सुंदर बड़ी बहन सुशीला से लगातार तुलना होने से मन्नू में हीन-भावना घर कर गई।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000045', 'मन्नू भंडारी की माँ का स्वभाव पिता के स्वभाव से किस प्रकार ठीक विपरीत था?', NULL, NULL, 'VSA', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 2, 'पिता जहाँ क्रोधी और अहंवादी थे, वहीं माँ अत्यंत सहनशील, धैर्यवती व धरती से भी ज्यादा सहनशक्ति रखने वाली थीं जो सबकी ज़िद व क्रोध चुपचाप सह लेती थीं।', 'माँ की सहनशीलता बनाम पिता का क्रोध (2M)', NULL, 'पिता जहाँ क्रोधी और अहंवादी थे, वहीं माँ अत्यंत सहनशील, धैर्यवती व धरती से भी ज्यादा सहनशक्ति रखने वाली थीं जो सबकी ज़िद व क्रोध चुपचाप सह लेती थीं।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000046', '(i) नवाब साहब पहले ही सफ़र में अकेले होने का संतोष क्यों कर रहे थे? (ii) लेखक के डिब्बे में चढ़ते ही उनके चेहरे पर कैसा भाव आया? (iii) खीरा तैयार करने में नवाब ने कितनी नफ़ासत दिखाई? (iv) आज के समय में "नवाबी दिखावा" कहाँ दिखता है?', NULL, NULL, 'CASE', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 4, '(i) अपनी तनहाई में तुच्छ माने जाने वाले खीरे शौक से खाने के लिए। (ii) असंतोष व एकांत में विघ्न पड़ने का भाव। (iii) तौलिया झाड़कर बिछाया, लोटे के पानी से खीरे धोए, झाग निकाला, फाँकें काटकर जीरा-नमक-लाल मिर्च बुरकी। (iv) दिखावटी स्टेटस सिंबल व सोशल मीडिया के झूठे प्रदर्शन में।', '4 × 1M = 4M', 'प्रसंग: सेकंड क्लास के खाली डिब्बे में सफेदपोश सज्जन ने अपने सामने तौलिए पर दो चिकने खीरे रखे थे, जिन्हें वे अकेले में खाने की तैयारी कर रहे थे।', '(i) अपनी तनहाई में तुच्छ माने जाने वाले खीरे शौक से खाने के लिए। (ii) असंतोष व एकांत में विघ्न पड़ने का भाव। (iii) तौलिया झाड़कर बिछाया, लोटे के पानी से खीरे धोए, झाग निकाला, फाँकें काटकर जीरा-नमक-लाल मिर्च बुरकी। (iv) दिखावटी स्टेटस सिंबल व सोशल मीडिया के झूठे प्रदर्शन में।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000047', '"शीला अग्रवाल ने साहित्य का दायरा बढ़ाया ही नहीं, बल्कि जिंदगी के यथार्थ से भी जोड़ा।" — "एक कहानी यह भी" के आधार पर सिद्ध कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 4, 'शीला अग्रवाल ने मन्नू को केवल कोर्स की किताबों तक सीमित न रखकर प्रेमचंद, शरत, जैनेंद्र, अज्ञेय और यशपाल की रचनाएँ पढ़ने व उन पर खुलकर बहस करने की प्रेरणा दी — जिससे 1946–47 के स्वतंत्रता आंदोलन में वे सड़कों पर नेतृत्व करने को तैयार हुईं।', 'साहित्यिक मार्गदर्शन (2M) + सक्रिय नेतृत्व निर्माण (2M)', NULL, 'शीला अग्रवाल ने मन्नू को केवल कोर्स की किताबों तक सीमित न रखकर प्रेमचंद, शरत, जैनेंद्र, अज्ञेय और यशपाल की रचनाएँ पढ़ने व उन पर खुलकर बहस करने की प्रेरणा दी — जिससे 1946–47 के स्वतंत्रता आंदोलन में वे सड़कों पर नेतृत्व करने को तैयार हुईं।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000048', 'दोनों पाठों ("लखनवी अंदाज़" और "एक कहानी यह भी") के सामाजिक यथार्थ की तुलना कीजिए — एक ओर झूठी शान का पतन है तो दूसरी ओर स्त्री-सशक्तिकरण एवं वैचारिक जागरण।', NULL, NULL, 'LA', 'Hindi', 'लखनवी अंदाज़ व एक कहानी यह भी', 5, 'यशपाल के "लखनवी अंदाज़" में नवाब साहब खोखले अतीत के गौरव और दिखावे से चिपके हुए यथार्थ से कटे दिखते हैं। इसके ठीक विपरीत, मन्नू भंडारी की आत्मकथ्यात्मक कहानी "एक कहानी यह भी" एक साधारण लड़की के हीन-भावना, पारिवारिक वर्जनाओं व पितृसत्तात्मक अंतर्विरोधों से निकलकर साहित्य और स्वाधीनता आंदोलन की प्रखर आवाज़ बनने की जीवंत गाथा है।', 'लखनवी अंदाज़ विश्लेषण (2M) + एक कहानी यह भी (2M) + तुलनात्मक निष्कर्ष (1M)', NULL, 'यशपाल के "लखनवी अंदाज़" में नवाब साहब खोखले अतीत के गौरव और दिखावे से चिपके हुए यथार्थ से कटे दिखते हैं। इसके ठीक विपरीत, मन्नू भंडारी की आत्मकथ्यात्मक कहानी "एक कहानी यह भी" एक साधारण लड़की के हीन-भावना, पारिवारिक वर्जनाओं व पितृसत्तात्मक अंतर्विरोधों से निकलकर साहित्य और स्वाधीनता आंदोलन की प्रखर आवाज़ बनने की जीवंत गाथा है।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000049', 'भारत-रत्न उस्ताद बिस्मिल्ला खाँ किस वाद्य यंत्र के विश्वविख्यात वादक थे?', '{"A":"तबला","B":"शहनाई (मंगल ध्वनि)","C":"सितार","D":"बाँसुरी"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'वे काशी में पंचगंगा घाट पर बालाजी मंदिर की ड्योढ़ी पर शहनाई बजाते थे।', NULL, NULL, 'वे काशी में पंचगंगा घाट पर बालाजी मंदिर की ड्योढ़ी पर शहनाई बजाते थे।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004a', 'बिस्मिल्ला खाँ का जन्म कहाँ हुआ था और उनका बचपन का नाम क्या था?', '{"A":"बनारस, सलीम","B":"डुमराँव (बिहार), अमीरुद्दीन","C":"लखनऊ, फैयाज","D":"अजमेर, रहीम"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'डुमराँव (बिहार) में जन्म और बचपन का नाम अमीरुद्दीन था।', NULL, NULL, 'डुमराँव (बिहार) में जन्म और बचपन का नाम अमीरुद्दीन था।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004b', 'काशी विश्वनाथ मंदिर और गंगा जी के प्रति बिस्मिल्ला खाँ की भावना कैसी थी?', '{"A":"अलगाव की","B":"अटूट श्रद्धा व हिंदू-मुस्लिम गंगा-जमुनी तहजीब की मिसाल (सच्चा सुर माँगते थे)","C":"केवल व्यावसायिक","D":"राजनीतिक"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'वे पाचों वक्त नमाज में सच्चा सुर माँगते और काशी छोड़कर कहीं जाने को तैयार न थे।', NULL, NULL, 'वे पाचों वक्त नमाज में सच्चा सुर माँगते और काशी छोड़कर कहीं जाने को तैयार न थे।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004c', 'भदंत आनंद कौसल्यायन के अनुसार "सभ्यता" और "संस्कृति" में क्या अंतर है?', '{"A":"दोनों एक ही हैं","B":"संस्कृति वह योग्यता/चेतना है जो आविष्कार कराती है, जबकि सभ्यता उस आविष्कार का भौतिक परिणाम है","C":"संस्कृति केवल धर्म है","D":"सभ्यता भाषा है"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'संस्कृति कारण/ऊर्जा है और सभ्यता उसका बाहरी परिणाम।', NULL, NULL, 'संस्कृति कारण/ऊर्जा है और सभ्यता उसका बाहरी परिणाम।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004d', 'आग और सुई-धागे के आविष्कारकर्ता को लेखक ने क्या माना है?', '{"A":"केवल मजदूर","B":"संस्कृत व्यक्ति (जिसकी बुद्धि ने कल्याणकारी खोज की)","C":"असभ्य व्यक्ति","D":"व्यापारी"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'मानव कल्याण के लिए पहला आविष्कार करने वाला "संस्कृत व्यक्ति" होता है।', NULL, NULL, 'मानव कल्याण के लिए पहला आविष्कार करने वाला "संस्कृत व्यक्ति" होता है।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004e', 'जब न्यूटन के सिद्धांतों को आज का विद्यार्थी रटकर प्रयोग करता है, तो वह कहलाता है:', '{"A":"संस्कृत व्यक्ति","B":"सभ्य व्यक्ति (क्योंकि वह बनी-बनाई जानकारी का उपयोग कर रहा है, नई खोज नहीं)","C":"महान दार्शनिक","D":"असंस्कृत"}'::jsonb, 'B', 'MCQ', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 1, 'न्यूटन संस्कृत थे; आज के हम केवल सभ्य हैं।', NULL, NULL, 'न्यूटन संस्कृत थे; आज के हम केवल सभ्य हैं।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000004f', 'बिस्मिल्ला खाँ को "शहनाई की मंगलध्वनि का नायक" क्यों कहा जाता है?', NULL, NULL, 'VSA', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 2, 'शहनाई मांगलिक अवसरों पर बजने वाला वाद्य है और 80 वर्ष की साधना के बाद भी वे खुदा से हर रोज़ सच्चे व असरदार सुर की दुआ करते रहे — जीवन भर संगीत की इबादत की।', 'मांगलिक वाद्य + आजीवन सुर साधना (2M)', NULL, 'शहनाई मांगलिक अवसरों पर बजने वाला वाद्य है और 80 वर्ष की साधना के बाद भी वे खुदा से हर रोज़ सच्चे व असरदार सुर की दुआ करते रहे — जीवन भर संगीत की इबादत की।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000050', 'सुषिर वाद्य किन्हें कहते हैं? शहनाई और मुरली में दो अन्य सुषिर वाद्य जोड़िए।', NULL, NULL, 'VSA', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 2, 'फूँक मारकर बजाए जाने वाले छिद्रयुक्त वाद्य यंत्र सुषिर वाद्य कहलाते हैं — जैसे शहनाई, बाँसुरी (मुरली), बीन, नादस्वरम।', 'परिभाषा (1M) + उदाहरण (1M)', NULL, 'फूँक मारकर बजाए जाने वाले छिद्रयुक्त वाद्य यंत्र सुषिर वाद्य कहलाते हैं — जैसे शहनाई, बाँसुरी (मुरली), बीन, नादस्वरम।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000051', 'मानव संस्कृति को "अविभाज्य वस्तु" क्यों कहा गया है?', NULL, NULL, 'VSA', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 2, 'क्योंकि पूरे विश्व की संस्कृतियों में कल्याणकारी ज्ञान व आविष्कार एक-दूसरे से आदान-प्रदान होकर जुड़ते रहते हैं; कल्याण की भावना को धर्म या सीमाओं में नहीं बाँटा जा सकता।', 'लोक-कल्याण की साझा विरासत (2M)', NULL, 'क्योंकि पूरे विश्व की संस्कृतियों में कल्याणकारी ज्ञान व आविष्कार एक-दूसरे से आदान-प्रदान होकर जुड़ते रहते हैं; कल्याण की भावना को धर्म या सीमाओं में नहीं बाँटा जा सकता।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000052', '(i) एक शिष्या ने जब बिस्मिल्ला खाँ से फटा तहमत न पहनने की गुज़ारिश की, तो उन्होंने क्या जवाब दिया? (ii) डुमराँव का शहनाई की दुनिया में क्या ऐतिहासिक महत्व है? (iii) खाँ साहब के लिए "काशी" और "गंगा" क्यों प्राण थे? (iv) वे भारत रत्न पाकर भी सादगी कैसे जीते रहे?', NULL, NULL, 'CASE', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 4, '(i) "अरे पगली, ये भारत रत्न हमको शहनाइया पे मिला है, लुँगिया पे नाहीं!" (ii) वहाँ की सोन नदी के किनारे उगने वाली नरकट घास से शहनाई की "रीड" बनती है। (iii) उनके पुरखों व संगीत की धरोहर यहीं बसी थी ("जन्नत" छोड़ने जैसा)। (iv) कचौड़ी-जलेबी व फटे तहमत की सादगी व अहंकारहीन सुर-साधना।', '4 × 1M = 4M', 'प्रसंग: भारत रत्न से सम्मानित होने पर भी उस्ताद बिस्मिल्ला खाँ ने काशी की गलियाँ, अपनी रियाज की सादगी और कचौड़ी-जलेबी का अपनापन कभी नहीं छोड़ा।', '(i) "अरे पगली, ये भारत रत्न हमको शहनाइया पे मिला है, लुँगिया पे नाहीं!" (ii) वहाँ की सोन नदी के किनारे उगने वाली नरकट घास से शहनाई की "रीड" बनती है। (iii) उनके पुरखों व संगीत की धरोहर यहीं बसी थी ("जन्नत" छोड़ने जैसा)। (iv) कचौड़ी-जलेबी व फटे तहमत की सादगी व अहंकारहीन सुर-साधना।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000053', '"संस्कृति जब कल्याण की भावना से नाता तोड़ लेती है तो वह असभ्यता बन जाती है।" — सिद्ध कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 4, 'यदि बुद्धि व आविष्कार का उपयोग मानवता को सुई-धागे या औषधि से जोड़ने के बजाय विनाशकारी अस्त्र-शस्त्र व युद्ध बनाने में हो, तो वह संस्कृति नहीं बल्कि असभ्यता बन जाती है।', 'विनाश बनाम कल्याण तर्क + उदाहरण (4M)', NULL, 'यदि बुद्धि व आविष्कार का उपयोग मानवता को सुई-धागे या औषधि से जोड़ने के बजाय विनाशकारी अस्त्र-शस्त्र व युद्ध बनाने में हो, तो वह संस्कृति नहीं बल्कि असभ्यता बन जाती है।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000054', '"नौबतखाने में इबादत" के उस्ताद बिस्मिल्ला खाँ और "संस्कृति" निबंध के आधार पर स्पष्ट कीजिए कि सच्ची कला, आस्था और सांस्कृतिक चेतना किसी संकीर्ण मजहब या स्वार्थ की सीमा में नहीं बँधती।', NULL, NULL, 'LA', 'Hindi', 'नौबतखाने में इबादत व संस्कृति', 5, 'बिस्मिल्ला खाँ पाँचों वक्त की नमाज़, मुहर्रम का मातम और काशी विश्वनाथ-बालाजी की आरती — सब में एक ही ईश्वर का सुर खोजते हैं। वहीं "संस्कृति" निबंध सिद्ध करता है कि चाहे बुद्ध का करुणा-त्याग हो, लेनिन का ब्रेड बाँटना हो या कार्ल मार्क्स का श्रमिक हित — जहाँ त्याग व मानव-कल्याण है, वहीं सच्ची संस्कृति बसती है।', 'बिस्मिल्ला खाँ का समन्वय (2.5M) + संस्कृति का मानवतावाद (2.5M)', NULL, 'बिस्मिल्ला खाँ पाँचों वक्त की नमाज़, मुहर्रम का मातम और काशी विश्वनाथ-बालाजी की आरती — सब में एक ही ईश्वर का सुर खोजते हैं। वहीं "संस्कृति" निबंध सिद्ध करता है कि चाहे बुद्ध का करुणा-त्याग हो, लेनिन का ब्रेड बाँटना हो या कार्ल मार्क्स का श्रमिक हित — जहाँ त्याग व मानव-कल्याण है, वहीं सच्ची संस्कृति बसती है।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000055', '"माता का अँचल" में भोलानाथ पिता के साथ अत्यधिक लगाव के बावजूद संकट आने पर किसकी शरण में गया?', '{"A":"बाबूजी के","B":"माँ के अँचल में (सच्ची सुरक्षा व ममता का अनुभव)","C":"दादाजी के","D":"मित्र के"}'::jsonb, 'B', 'MCQ', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 1, 'साँप के भय से घबराकर वह सीधे माँ के आंचल में छिप गया।', NULL, NULL, 'साँप के भय से घबराकर वह सीधे माँ के आंचल में छिप गया।', 'EASY', true),
