        ('10051111-0000-4000-8000-000000000059', '"कटाओ" को लेखिका ने क्या कहा है?', '{"A":"भारत का पेरिस","B":"भारत का स्विट्जरलैंड (अभी तक टूरिस्ट स्पॉट न बनने से अनछुई सुंदरता)","C":"रेगिस्तान","D":"मरुस्थल"}'::jsonb, 'B', 'MCQ', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 1, 'व्यावसायिक भीड़ से दूर बर्फीला कटाओ।', NULL, NULL, 'व्यावसायिक भीड़ से दूर बर्फीला कटाओ।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000005a', '"मैं क्यों लिखता हूँ?" में अज्ञेय ने लेखन का मुख्य आंतरिक कारण किसे माना है?', '{"A":"केवल धन व प्रसिद्धि","B":"भीतरी विवशता — प्रत्यक्ष अनुभव जब \"अनुभूति\" बनकर बाहर आना चाहता है (जैसे हिरोशिमा के जले पत्थर की छाया देख कविता फूटी)","C":"संपादक का डर","D":"प्रतियोगिता"}'::jsonb, 'B', 'MCQ', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 1, 'आंतरिक अनुभूति और विवशता ही सच्ची रचना कराती है।', NULL, NULL, 'आंतरिक अनुभूति और विवशता ही सच्ची रचना कराती है।', 'EASY', true),
        ('10051111-0000-4000-8000-00000000005b', 'भोलानाथ के बाबूजी उन्हें कैसे स्नेह करते थे और "गोरस-भात" माँ के हाथ से खाने में क्या अंतर था?', NULL, NULL, 'VSA', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 2, 'बाबूजी उन्हें नहलाकर भभूत का तिलक लगाते, कंधे पर बैठाकर गंगा तट पर मछलियों को आटे की गोलियाँ खिलाते। फिर भी माँ तोता-मैना, कबूतर-मोर के बनावटी कौर गिनकर जब तक "ददरी" भर के न खिलातीं, पेट भरता ही न था।', 'बाबूजी का स्नेह (1M) + माँ का वात्सल्य (1M)', NULL, 'बाबूजी उन्हें नहलाकर भभूत का तिलक लगाते, कंधे पर बैठाकर गंगा तट पर मछलियों को आटे की गोलियाँ खिलाते। फिर भी माँ तोता-मैना, कबूतर-मोर के बनावटी कौर गिनकर जब तक "ददरी" भर के न खिलातीं, पेट भरता ही न था।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000005c', 'गंगटोक शहर को "मेहनतकश बादशाहों का शहर" क्यों कहा गया है?', NULL, NULL, 'VSA', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 2, 'पहाड़ी ढलानों पर बसे इस शहर की एक-एक ईंट, सड़कें और सीढ़ियाँ वहाँ की स्त्री-पुरुषों (यहाँ तक कि पीठ पर बच्चे बाँधे पत्थर तोड़ती पहाड़िनों) के कठोर परिश्रम का प्रमाण हैं।', 'कठोर परिश्रम व निर्माण का कारण (2M)', NULL, 'पहाड़ी ढलानों पर बसे इस शहर की एक-एक ईंट, सड़कें और सीढ़ियाँ वहाँ की स्त्री-पुरुषों (यहाँ तक कि पीठ पर बच्चे बाँधे पत्थर तोड़ती पहाड़िनों) के कठोर परिश्रम का प्रमाण हैं।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000005d', 'अज्ञेय के अनुसार "प्रत्यक्ष अनुभव" और "अनुभूति" में क्या अंतर है?', NULL, NULL, 'VSA', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 2, 'अनुभव वह है जो घटना के समय हम बाहरी आँखों से देखते या भोगते हैं (जैसे हिरोशिमा अस्पताल देखना), किंतु अनुभूति वह है जब संवेदना व कल्पना मन को भीतर तक झकझोर कर रचना को जन्म देती है (जले पत्थर पर मानव छाया देखकर कविता फूटना)।', 'बाहरी घटना बनाम गहरी संवेदना (2M)', NULL, 'अनुभव वह है जो घटना के समय हम बाहरी आँखों से देखते या भोगते हैं (जैसे हिरोशिमा अस्पताल देखना), किंतु अनुभूति वह है जब संवेदना व कल्पना मन को भीतर तक झकझोर कर रचना को जन्म देती है (जले पत्थर पर मानव छाया देखकर कविता फूटना)।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-00000000005e', '(i) पहाड़िनों को पीठ पर बच्चे बाँधकर कुदाल चलाते देख लेखिका को क्या बोध हुआ? (ii) हिमालय में जगह-जगह लगे "देश की सीमा पर बैठे फौजियों" के बोर्ड क्या याद दिलाते हैं? (iii) पर्यावरण प्रदूषण से बर्फ कम होने की बात गाइड जितेन ने कैसे बताई? (iv) "स्नो फॉल" की उम्मीद ने सैलानियों को क्या सिखाया?', NULL, NULL, 'CASE', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 4, '(i) "कितना कम लेकर ये समाज को कितना अधिक वापस लौटाती हैं!" (ii) माइनस 15 डिग्री में भी जवान जागकर हमारी सुरक्षित नींद और चैन सुनिश्चित करते हैं। (iii) बढ़ते प्रदूषण व पेड़ों की कटाई से अब लायुंग में बर्फबारी घट रही है। (iv) अनछुए कटाओ में प्रकृति को बिना गंदगी फैलाए सहेजना चाहिए।', '4 × 1M = 4M', 'प्रसंग: युमथांग और लायुंग की ऊँचाइयों पर जाते हुए लेखिका ने एक ओर अद्भुत प्रकृति देखी और दूसरी ओर खतरनाक पहाड़ी मोड़ों पर रास्ता काटती श्रमजीवी महिलाओं का संघर्ष देखा।', '(i) "कितना कम लेकर ये समाज को कितना अधिक वापस लौटाती हैं!" (ii) माइनस 15 डिग्री में भी जवान जागकर हमारी सुरक्षित नींद और चैन सुनिश्चित करते हैं। (iii) बढ़ते प्रदूषण व पेड़ों की कटाई से अब लायुंग में बर्फबारी घट रही है। (iv) अनछुए कटाओ में प्रकृति को बिना गंदगी फैलाए सहेजना चाहिए।', 'HARD', true),
        ('10051111-0000-4000-8000-00000000005f', 'शहरीकरण और बच्चों के आधुनिक एकाकी खेलों की तुलना "माता का अँचल" के सामूहिक बचपन से कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 4, 'पहले बच्चे मिट्टी, लकड़ी, आम-बगीचों में मिलकर खेती, मिठाई की दुकान व बारात के खेल रचते थे जिससे प्रकृति-प्रेम व सामाजिकता बढ़ती थी; आज मोबाइल व एकाकी कमरों में बचपन सिमट गया है, यद्यपि संकट के समय माँ की गोद आज भी वही परम आश्रय है।', 'तुलना (3M) + मातृ-सुरक्षा निष्कर्ष (1M)', NULL, 'पहले बच्चे मिट्टी, लकड़ी, आम-बगीचों में मिलकर खेती, मिठाई की दुकान व बारात के खेल रचते थे जिससे प्रकृति-प्रेम व सामाजिकता बढ़ती थी; आज मोबाइल व एकाकी कमरों में बचपन सिमट गया है, यद्यपि संकट के समय माँ की गोद आज भी वही परम आश्रय है।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000060', '"प्रत्येक श्रेष्ठ रचना के पीछे बाहरी दबाव से अधिक लेखक की आंतरिक अनुभूति, संवेदना और मानवता के प्रति चिंता होती है।" — अज्ञेय के "मैं क्यों लिखता हूँ" तथा "साना-साना हाथ जोड़ि" के आधार पर सिद्ध कीजिए।', NULL, NULL, 'LA', 'Hindi', 'कृतिका: माता का अँचल, साना-साना हाथ जोड़ि व मैं क्यों लिखता हूँ', 5, 'अज्ञेय समझाते हैं कि संपादक की माँग या आर्थिक आवश्यकता कभी बाहरी निमित्त हो सकती है, पर सच्ची कविता हिरोशिमा में जले पत्थर पर मानव-छाया देखकर उपजी आंतरिक पीड़ा से ही फूटती है। यही संवेदना मधु कांकरिया में तब जागती है जब वे एक ओर टिस्ता नदी और हिमालयी सौंदर्य से अभिभूत होती हैं, और दूसरी ओर पत्थर तोड़ती पहाड़ी महिलाओं व माइनस तापमान में खड़े जवानों के प्रति कृतज्ञ हो उठती हैं।', 'अज्ञेय सिद्धांत व हिरोशिमा (3M) + मधु कांकरिया संवेदना (2M)', NULL, 'अज्ञेय समझाते हैं कि संपादक की माँग या आर्थिक आवश्यकता कभी बाहरी निमित्त हो सकती है, पर सच्ची कविता हिरोशिमा में जले पत्थर पर मानव-छाया देखकर उपजी आंतरिक पीड़ा से ही फूटती है। यही संवेदना मधु कांकरिया में तब जागती है जब वे एक ओर टिस्ता नदी और हिमालयी सौंदर्य से अभिभूत होती हैं, और दूसरी ओर पत्थर तोड़ती पहाड़ी महिलाओं व माइनस तापमान में खड़े जवानों के प्रति कृतज्ञ हो उठती हैं।', 'HARD', true),
        ('10051111-0000-4000-8000-000000000061', '"ज्यों ही वर्षा शुरू हुई, त्यों ही मोर नाचने लगे" — रचना के आधार पर यह कौन-सा वाक्य है?', '{"A":"सरल वाक्य","B":"संयुक्त वाक्य","C":"मिश्र वाक्य","D":"विस्मयादिबोधक वाक्य"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्यावहारिक व्याकरण: रचना के आधार पर वाक्य भेद व वाच्य', 1, '"ज्यों ही... त्यों ही" आश्रित उपवाक्य जोड़ने से मिश्र वाक्य है।', NULL, NULL, '"ज्यों ही... त्यों ही" आश्रित उपवाक्य जोड़ने से मिश्र वाक्य है।', 'EASY', true),
