        ('10051111-0000-4000-8000-000000000064', '"तुलसीदास ने रामचरितमानस की रचना की" का सही कर्मवाच्य रूपांतरण होगा:', '{"A":"तुलसीदास रामचरितमानस रचते हैं।","B":"तुलसीदास द्वारा रामचरितमानस की रचना की गई।","C":"तुलसीदास से रचना नहीं होती।","D":"रामचरितमानस ने तुलसी को रचा।"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्यावहारिक व्याकरण: रचना के आधार पर वाक्य भेद व वाच्य', 1, '"द्वारा" + कर्म प्रधान भूतकाल क्रिया।', NULL, NULL, '"द्वारा" + कर्म प्रधान भूतकाल क्रिया।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000065', '"वह बाज़ार गया क्योंकि उसे पुस्तक खरीदनी थी" को सरल वाक्य में बदलिए:', '{"A":"वह बाज़ार जाकर पुस्तक लाएगा।","B":"वह पुस्तक खरीदने के लिए बाज़ार गया।","C":"जब वह बाज़ार गया तब पुस्तक खरीदी।","D":"उसने पुस्तक खरीदी और घर आया।"}'::jsonb, 'B', 'MCQ', 'Hindi', 'व्यावहारिक व्याकरण: रचना के आधार पर वाक्य भेद व वाच्य', 1, 'एक ही मुख्य क्रिया ("गया") वाला सरल वाक्य।', NULL, NULL, 'एक ही मुख्य क्रिया ("गया") वाला सरल वाक्य।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000066', 'किस वाच्य में क्रिया हमेशा अकर्मक, अन्यपुरुष, पुल्लिंग और एकवचन में रहती है?', '{"A":"कर्तृवाच्य","B":"कर्मवाच्य","C":"भाववाच्य","D":"तीनों में"}'::jsonb, 'C', 'MCQ', 'Hindi', 'व्यावहारिक व्याकरण: रचना के आधार पर वाक्य भेद व वाच्य', 1, 'भाववाच्य की अनिवार्य व्याकरणिक पहचान।', NULL, NULL, 'भाववाच्य की अनिवार्य व्याकरणिक पहचान।', 'EASY', true),
        ('10051111-0000-4000-8000-000000000067', 'सरल, संयुक्त और मिश्र वाक्य की पहचान एक-एक उदाहरण सहित लिखिए।', NULL, NULL, 'VSA', 'Hindi', 'व्यावहारिक व्याकरण: रचना के आधार पर वाक्य भेद व वाच्य', 2, 'सरल (1 उद्देश्य+1 विधेय): वह पढ़कर सो गया। संयुक्त (स्वतंत्र योजक और/परंतु): वह पढ़ा और सो गया। मिश्र (प्रधान+आश्रित जब/जो/कि): जब उसने पढ़ लिया, तब वह सो गया।', 'तीनों भेद उदाहरण सहित (2M)', NULL, 'सरल (1 उद्देश्य+1 विधेय): वह पढ़कर सो गया। संयुक्त (स्वतंत्र योजक और/परंतु): वह पढ़ा और सो गया। मिश्र (प्रधान+आश्रित जब/जो/कि): जब उसने पढ़ लिया, तब वह सो गया।', 'MEDIUM', true),
        ('10051111-0000-4000-8000-000000000068', 'वाच्य परिवर्तन कीजिए:
